	public int loadHighScore()
	{
		return loadInt(KEY_HIGH_SCORE);
	}

	public long loadLifetimeXpTenths()
	{
		return MoreObjects.firstNonNull(
			configManager.getConfiguration(TrappyChinchompaConfig.GROUP, KEY_LIFETIME_XP, Long.class), 0L);
	}

	private int loadInt(String key)
	{
		return MoreObjects.firstNonNull(
			configManager.getConfiguration(TrappyChinchompaConfig.GROUP, key, Integer.class), 0);
	}

	/** Per-difficulty tallies for the stats card; zeros on a fresh install. */
	public DifficultyStats loadStats(Difficulty difficulty)
	{
		return new DifficultyStats(
			loadInt(KEY_STAT_RUNS + difficulty.name()),
			loadInt(KEY_STAT_BEST + difficulty.name()),
			MoreObjects.firstNonNull(configManager.getConfiguration(TrappyChinchompaConfig.GROUP,
				KEY_STAT_XP + difficulty.name(), Long.class), 0L),
			MoreObjects.firstNonNull(configManager.getConfiguration(TrappyChinchompaConfig.GROUP,
				KEY_STAT_POLES + difficulty.name(), Long.class), 0L));
	}

	/**
	 * Persist one finished run and fold it into the lifetime tally.
	 * Called from the EDT on the RUNNING -> DEAD transition; writes are
	 * per-death, never per-frame (ConfigManager flushes are not free).
	 * The run's locked-in difficulty scales the xp and gates the record.
	 */
	public RunResult recordRun(int score, Difficulty difficulty, BackgroundTheme runZone,
		ChinSkin runSkin)
	{
		final int previousBest = loadHighScore();
		final boolean newBest = difficulty.countsForRecords() && score > previousBest;
		final int best = newBest ? score : previousBest;
		if (newBest)
		{
			configManager.setConfiguration(TrappyChinchompaConfig.GROUP, KEY_HIGH_SCORE,
				String.valueOf(best));
		}

		final long before = loadLifetimeXpTenths();
		final long runXp = difficulty.xpTenthsForRun(score);
		final long lifetime = before + runXp;
		if (runXp > 0)
		{
			configManager.setConfiguration(TrappyChinchompaConfig.GROUP, KEY_LIFETIME_XP,
				String.valueOf(lifetime));
		}

		// Per-difficulty tallies (Easy keeps its own casual best here even
		// though it never touches the unlock record above).
		final DifficultyStats stats = loadStats(difficulty);
		final boolean newDifficultyBest = score > stats.getBest();
		final int difficultyBest = Math.max(stats.getBest(), score);
		configManager.setConfiguration(TrappyChinchompaConfig.GROUP,
			KEY_STAT_RUNS + difficulty.name(), String.valueOf(stats.getRuns() + 1));
		if (newDifficultyBest)
		{
			configManager.setConfiguration(TrappyChinchompaConfig.GROUP,
				KEY_STAT_BEST + difficulty.name(), String.valueOf(score));
		}
		if (runXp > 0)
		{
			configManager.setConfiguration(TrappyChinchompaConfig.GROUP,
				KEY_STAT_XP + difficulty.name(), String.valueOf(stats.getXpTenths() + runXp));
		}
		if (score > 0)
		{
			configManager.setConfiguration(TrappyChinchompaConfig.GROUP,
				KEY_STAT_POLES + difficulty.name(), String.valueOf(stats.getPoles() + score));
		}

		final int levelBefore = HunterXp.levelForXpTenths(before);
		final int levelAfter = HunterXp.levelForXpTenths(lifetime);
		final int leveledTo = levelAfter > levelBefore ? levelAfter : 0;

		// Achievements: score milestones, the zero-pole special, level
		// milestones, the zone/skin-bound feats, and the streak counters.
		final List<String> candidates = new ArrayList<>(Achievement.scoreIds(difficulty, score));
		if (score == 0)
		{
			candidates.add(Achievement.ID_ZERO_POLES);
		}
		candidates.addAll(Achievement.levelIds(levelAfter));
		if (runXp >= Achievement.PRIF_RUN_XP_TENTHS && runZone == BackgroundTheme.PRIFDDINAS)
		{
			candidates.add(Achievement.ID_PRIF_25K);
		}
		if (score >= 1 && runSkin == ChinSkin.CABBAGE && runZone == BackgroundTheme.INFERNO)
		{
			candidates.add(Achievement.ID_CABBAGE_INFERNO);
		}
		for (int threshold : Achievement.STREAK_THRESHOLDS)
		{
			final int streak = score >= threshold ? loadStreak(difficulty, threshold) + 1 : 0;
			saveStreak(difficulty, threshold, streak);
			candidates.addAll(Achievement.streakIds(difficulty, threshold, streak));
		}
		final List<Achievement> newAchievements = earn(candidates);

		UnlockState.update(best, levelAfter, loadEarnedAchievements());
		return new RunResult(score, runXp, lifetime, levelAfter, leveledTo,
			BackgroundTheme.newlyUnlocked(levelBefore, levelAfter),
			newBest ? ChinSkin.newlyUnlocked(previousBest, score) : null,
			newAchievements, difficultyBest, newDifficultyBest);
	}
}

package com.trappychinchompa;

import java.util.Collections;
import java.util.Set;

/**
 * Current unlock progress, published by the plugin so picker enums can
 * render lock-aware labels and answer isUnlocked without a plugin handle.
 */
public final class UnlockState
{
	private static volatile int bestScore;
	private static volatile int antiHunterLevel = 1;
	private static volatile Set<String> earnedAchievements = Collections.emptySet();
	/** Developer-mode override: everything reads as unlocked. Session-only. */
	private static volatile boolean devUnlockAll;

	private UnlockState()
	{
	}

	/** Full update, as the plugin publishes it. */
	public static void update(int newBestScore, int newAntiHunterLevel, Set<String> earned)
	{
		bestScore = newBestScore;
		antiHunterLevel = newAntiHunterLevel;
		earnedAchievements = earned == null ? Collections.emptySet() : earned;
	}

	/** Convenience for tests: resets the earned set and the dev override. */
	public static void update(int newBestScore, int newAntiHunterLevel)
	{
		update(newBestScore, newAntiHunterLevel, Collections.emptySet());
		devUnlockAll = false;
	}

	public static boolean isDevUnlockAll()
	{
		return devUnlockAll;
	}

	public static void setDevUnlockAll(boolean on)
	{
		devUnlockAll = on;
	}

	public static int getBestScore()
	{
		return bestScore;
	}

	public static int getAntiHunterLevel()
	{
		return antiHunterLevel;
	}

	public static Set<String> getEarnedAchievements()
	{
		return earnedAchievements;
	}
}

package com.trappychinchompa.duel;

import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.util.Text;

/**
 * The chatbox side of duels: right-click any player's name for "Duel",
 * or the pending challenger's name for "Accept duel" / "Decline duel".
 * Runs on the client thread; the controller is reached through the EDT.
 */
@Slf4j
public final class DuelChat
{
	public interface Actions
	{
		/** Name of the player whose challenge is waiting on us, or null. Read on the client thread. */
		String pendingChallenger();

		/** True while a fresh challenge could be sent (relay online, nothing in flight). */
		boolean canChallenge();

		void challengeFromChat(String name);

		void acceptFromChat();

		void declineFromChat();
	}

	static final String DUEL = "Duel";
	static final String ACCEPT = "Accept duel";
	static final String DECLINE = "Decline duel";

	private final Client client;
	private final Actions actions;

	public DuelChat(Client client, Actions actions)
	{
		this.client = client;
		this.actions = actions;
	}

	/** Do the accept/decline options belong on this chat name? */
	public static boolean menuFor(String pendingChallenger, String target)
	{
		if (pendingChallenger == null || target == null)
		{
			return false;
		}
		return Names.same(Text.removeTags(pendingChallenger), Text.removeTags(target));
	}

	/** The chatbox's own player options that the duel entries sit beside. */
	public static boolean anchorOption(String option)
	{
		return "Message".equals(option) || "Add ignore".equals(option);
	}

	/** Called from the plugin's MenuEntryAdded subscriber. */
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		// Chat-line player options are low priority ("Walk here" outranks them), so accept both kinds.
		final boolean componentOp = event.getType() == MenuAction.CC_OP.getId()
			|| event.getType() == MenuAction.CC_OP_LOW_PRIORITY.getId();
		if (!componentOp || !anchorOption(event.getOption()))
		{
			return;
		}
		if (WidgetUtil.componentToInterface(event.getActionParam1()) != InterfaceID.CHATBOX)
		{
			return;
		}
		final String target = event.getTarget();
		final String name = Text.toJagexName(Text.removeTags(target));
		if (menuFor(actions.pendingChallenger(), target))
		{
			client.createMenuEntry(-1)
				.setOption(DECLINE)
				.setTarget(target)
				.setType(MenuAction.RUNELITE)
				.onClick(e -> SwingUtilities.invokeLater(actions::declineFromChat));
			client.createMenuEntry(-1)
				.setOption(ACCEPT)
				.setTarget(target)
				.setType(MenuAction.RUNELITE)
				.onClick(e -> SwingUtilities.invokeLater(actions::acceptFromChat));
			return;
		}
		if (actions.canChallenge() && !name.isEmpty())
		{
			client.createMenuEntry(-1)
				.setOption(DUEL)
				.setTarget(target)
				.setType(MenuAction.RUNELITE)
				.onClick(e -> SwingUtilities.invokeLater(() -> actions.challengeFromChat(name)));
		}
	}
}

package com.trappychinchompa.duel;

import com.trappychinchompa.Difficulty;
import java.util.Locale;

/**
 * The typed side of duels: {@code ::duel <player> trappy [1|3|5]
 * [best|avg] [easy|normal|hard]}, plus {@code ::duel accept|no|gg}.
 * RuneLite hands us the words; the command never reaches the game.
 */
public final class DuelCommand
{
	public static final String USAGE = "Usage: ::duel <player> trappy [1|3|5] [best|avg] [easy|normal|hard], or ::duel accept | no | gg";
	private static final String[] GAME_TOKENS = {"trappy", "tc", "chin", "chinchompa", "trappychinchompa", "trappy-chinchompa"};

	public enum Kind
	{
		CHALLENGE, ACCEPT, DECLINE, CONCEDE, USAGE, NOT_OURS
	}

	private final Kind kind;
	private final String player;
	private final DuelRules rules;

	private DuelCommand(Kind kind, String player, DuelRules rules)
	{
		this.kind = kind;
		this.player = player;
		this.rules = rules;
	}

	public Kind getKind()
	{
		return kind;
	}

	public String getPlayer()
	{
		return player;
	}

	public DuelRules getRules()
	{
		return rules;
	}

	public static DuelCommand parse(String[] args, Difficulty current)
	{
		if (args == null || args.length == 0 || args[0].isEmpty())
		{
			return new DuelCommand(Kind.USAGE, null, null);
		}
		String first = args[0].toLowerCase(Locale.ROOT);
		switch (first)
		{
			case "accept":
			case "yes":
			case "ok":
				return new DuelCommand(Kind.ACCEPT, null, null);
			case "no":
			case "decline":
				return new DuelCommand(Kind.DECLINE, null, null);
			case "gg":
			case "concede":
			case "forfeit":
				return new DuelCommand(Kind.CONCEDE, null, null);
			default:
				break;
		}
		if (args.length < 2)
		{
			return new DuelCommand(Kind.USAGE, null, null);
		}
		String game = args[1].toLowerCase(Locale.ROOT);
		if (!isOurs(game))
		{
			// Another plugin's game, or a slot the player forgot to fill.
			return new DuelCommand(game.matches("[0-9]+|best|avg|average|easy|normal|hard") ? Kind.USAGE : Kind.NOT_OURS, null, null);
		}
		int series = 3;
		DuelRules.Metric metric = DuelRules.Metric.BEST_ROUND;
		Difficulty difficulty = current;
		for (int i = 2; i < args.length; i++)
		{
			String w = args[i].toLowerCase(Locale.ROOT);
			switch (w)
			{
				case "1":
				case "3":
				case "5":
					series = w.charAt(0) - '0';
					break;
				case "best":
				case "bs":
					metric = DuelRules.Metric.BEST_ROUND;
					break;
				case "avg":
				case "average":
				case "av":
					metric = DuelRules.Metric.AVERAGE;
					break;
				case "easy":
					difficulty = Difficulty.EASY;
					break;
				case "normal":
					difficulty = Difficulty.NORMAL;
					break;
				case "hard":
					difficulty = Difficulty.HARD;
					break;
				default:
					return new DuelCommand(Kind.USAGE, null, null);
			}
		}
		String player = args[0].replace('_', ' ').trim();
		return new DuelCommand(Kind.CHALLENGE, player, new DuelRules(difficulty, metric, series));
	}

	/** The typed form of a challenge: "::duel test_purr trappy 1 avg easy" (defaults left out). */
	public static String format(String player, DuelRules rules, Difficulty current)
	{
		StringBuilder sb = new StringBuilder("::duel ").append(player.trim().replace(' ', '_')).append(" trappy ")
			.append(rules.getSeries());
		if (rules.getMetric() == DuelRules.Metric.AVERAGE)
		{
			sb.append(" avg");
		}
		if (rules.getDifficulty() != current)
		{
			sb.append(' ').append(rules.getDifficulty().name().toLowerCase(Locale.ROOT));
		}
		return sb.toString();
	}

	private static boolean isOurs(String token)
	{
		for (String t : GAME_TOKENS)
		{
			if (t.equals(token))
			{
				return true;
			}
		}
		return false;
	}
}

package com.trappychinchompa.duel;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.Executor;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.Supplier;

/**
 * Duels from the plugin's side: the relay connection, the challenge
 * lobby (sent / incoming / queued for compete), and the ledger of duels
 * in flight. Driven on the EDT; talks back through notices and a
 * repaint hook.
 */
public final class DuelController implements RelayClient.Lobby
{
	/** The game id every message and room carries. */
	public static final String GAME = "tc1";
	static final long TOUCH_EVERY_MS = 60_000;
	/** Matchmaking gives up after this; the player retries by hand. */
	static final long QUEUE_LIMIT_MS = 30_000;

	public enum Phase
	{
		IDLE,
		/** Our challenge is out; waiting for their answer. */
		SENT,
		/** Their challenge is in; accept or decline. */
		INCOMING,
		/** Waiting in the compete queue. */
		QUEUED
	}

	private final RelayClient relay;
	private final BooleanSupplier blocked;
	private final Consumer<String> notice;
	private final Runnable changed;
	/** The canvas is handed a record whose next game has its seed. */
	private final Consumer<DuelRecord> ready;
	/** Names whose challenges are declined without a word. */
	private final Supplier<Set<String>> blockList;
	private String pendingPlay;

	private DuelLedger ledger = new DuelLedger("");
	private Phase phase = Phase.IDLE;
	private String opponent;
	private DuelRules rules;
	private String playingId;
	private long lastTouch;
	private long queuedAt;
	/** The rules of a compete that found nobody, until retried or dismissed. */
	private DuelRules noMatch;
	private final Map<String, List<Map<String, Object>>> boards = new HashMap<>();
	private final Map<String, List<Map<String, Object>>> ranks = new HashMap<>();
	/** The relay said the boards it sent are the developer-mode shadow. */
	private boolean devBoards;

	public DuelController(String relayUrl, RelayClient.Socket socket, Executor callbacks, RelayClient.Scheduler scheduler,
		BooleanSupplier blocked, Consumer<String> notice, Runnable changed, Consumer<DuelRecord> ready, Supplier<Set<String>> blockList,
		com.google.gson.Gson gson)
	{
		this.relay = new RelayClient(relayUrl, socket, callbacks, scheduler, this, gson);
		this.blocked = blocked;
		this.notice = notice;
		this.changed = changed;
		this.ready = ready;
		this.blockList = blockList;
	}

	// ---- relay lifecycle ----

	/** account = RuneLite's account hash as text; the relay binds the name to it. */
	public void connect(String displayName, String account, boolean hidden, boolean dev)
	{
		ledger = new DuelLedger(displayName);
		relay.connect(displayName, GAME, account, hidden, dev);
	}

	public void disconnect()
	{
		relay.disconnect();
		phase = Phase.IDLE;
		playingId = null;
		changed.run();
	}

	public boolean isOnline()
	{
		return relay.isOnline();
	}

	public String getName()
	{
		return relay.getName();
	}

	/** Once a second from the plugin: keeps the duel being played alive on the relay. */
	public void tick(long now)
	{
		if (playingId != null && now - lastTouch >= TOUCH_EVERY_MS)
		{
			lastTouch = now;
			relay.touch(playingId);
		}
		if (phase == Phase.QUEUED && queuedAt > 0 && now - queuedAt >= QUEUE_LIMIT_MS)
		{
			relay.uncompete();
			noMatch = rules;
			reset();
		}
	}

	/** A compete that timed out, waiting for Retry or Dismiss; null otherwise. */
	public DuelRules getNoMatch()
	{
		return noMatch;
	}

	public void retryCompete()
	{
		DuelRules again = noMatch;
		noMatch = null;
		if (again != null)
		{
			compete(again);
		}
	}

	public void dismissNoMatch()
	{
		noMatch = null;
		changed.run();
	}

	// ---- queries ----

	public Phase getPhase()
	{
		return phase;
	}

	public String getOpponent()
	{
		return opponent;
	}

	public DuelRules getRules()
	{
		return rules;
	}

	public DuelLedger getLedger()
	{
		return ledger;
	}

	public String getPlayingId()
	{
		return playingId;
	}

	public List<Map<String, Object>> board(String key)
	{
		return boards.get(key);
	}

	public List<Map<String, Object>> rankings(String key)
	{
		return ranks.get(key);
	}

	public boolean isDevBoards()
	{
		return devBoards;
	}

	/** The player whose challenge is waiting on us, for the right-click menu. */
	public String pendingChallenger()
	{
		return phase == Phase.INCOMING ? opponent : null;
	}

	/** Settled duels not yet announced, once each. */
	public List<DuelRecord> freshlySettled()
	{
		return ledger.freshlySettled();
	}

	// ---- what the player does ----

	public boolean challenge(String player, DuelRules newRules)
	{
		if (!relay.isOnline())
		{
			notice.accept("Duels need the relay: turn duels on in the plugin settings and log in.");
			return false;
		}
		if (phase != Phase.IDLE)
		{
			notice.accept("Answer the current challenge first.");
			return false;
		}
		if (blocked.getAsBoolean())
		{
			notice.accept("Duels are off while dev toggles are on.");
			return false;
		}
		if (player == null || player.trim().isEmpty() || Names.same(player, relay.getName()))
		{
			notice.accept(DuelCommand.USAGE);
			return false;
		}
		opponent = player.trim();
		rules = newRules;
		relay.challenge(opponent, GAME, rulesData(newRules));
		phase = Phase.SENT;
		changed.run();
		return true;
	}

	public boolean accept()
	{
		if (phase != Phase.INCOMING)
		{
			return false;
		}
		if (blocked.getAsBoolean())
		{
			notice.accept("Duels are off while dev toggles are on.");
			return false;
		}
		relay.accept(opponent, GAME, rulesData(rules));
		reset();
		return true;
	}

	public void decline()
	{
		if (phase == Phase.INCOMING)
		{
			relay.decline(opponent, GAME, rulesData(rules));
			reset();
		}
	}

	/** Withdraw a sent challenge, drop a pending one, or leave the queue. */
	public void cancel()
	{
		switch (phase)
		{
			case SENT:
				relay.decline(opponent, GAME, rulesData(rules));
				reset();
				break;
			case INCOMING:
				decline();
				break;
			case QUEUED:
				uncompete();
				break;
			default:
				break;
		}
	}

	public boolean compete(DuelRules competeRules)
	{
		if (!relay.isOnline())
		{
			notice.accept("Duels need the relay: turn duels on in the plugin settings and log in.");
			return false;
		}
		if (phase != Phase.IDLE || blocked.getAsBoolean())
		{
			return false;
		}
		rules = competeRules;
		opponent = null;
		noMatch = null;
		relay.compete(GAME, competeRules.canonical());
		phase = Phase.QUEUED;
		queuedAt = System.currentTimeMillis();
		changed.run();
		return true;
	}

	public void uncompete()
	{
		if (phase == Phase.QUEUED)
		{
			relay.uncompete();
			reset();
		}
	}

	/**
	 * Play pressed. With the seed already revealed the record comes back to
	 * start on; otherwise the relay is asked and the record arrives through
	 * the ready callback. Null means nothing to play right now.
	 */
	public DuelRecord play(String id)
	{
		DuelRecord r = ledger.get(id);
		if (r == null || r.isDone() || r.nextGame() == 0 || blocked.getAsBoolean() || id.equals(playingId))
		{
			// Already being played: a second Play must not restart the run.
			return null;
		}
		playingId = id;
		// The first tick touches right away; then once a minute.
		lastTouch = Long.MIN_VALUE / 2;
		if (r.hasSeed(r.nextGame()))
		{
			pendingPlay = null;
			changed.run();
			return r;
		}
		pendingPlay = id;
		relay.start(id, r.nextGame());
		changed.run();
		return null;
	}

	public void stopPlaying()
	{
		playingId = null;
		pendingPlay = null;
		changed.run();
	}

	/** A duel game finished on this client. */
	public void gameEnded(String id, int gameIndex, int score, List<Integer> flaps, int ticks)
	{
		playingId = null;
		relay.report(id, gameIndex, score, flaps, ticks);
		changed.run();
	}

	public void concede(String id)
	{
		if (ledger.get(id) != null)
		{
			relay.concede(id);
		}
		if (id.equals(playingId))
		{
			playingId = null;
		}
	}

	/** Concede whatever is being played, else the first duel still open. */
	public void concedeCurrent()
	{
		String id = playingId;
		if (id == null)
		{
			for (DuelRecord r : ledger.duels())
			{
				if (!r.isDone())
				{
					id = r.getId();
					break;
				}
			}
		}
		if (id != null)
		{
			concede(id);
		}
	}

	public void dismiss(String id)
	{
		ledger.dismiss(id);
		changed.run();
	}

	public void refreshBoards(String key)
	{
		if (relay.isOnline())
		{
			relay.board(GAME, key);
			relay.ranks(GAME, key);
		}
	}

	public void refreshHistory()
	{
		if (relay.isOnline())
		{
			relay.history(GAME);
		}
	}

	// ---- relay lobby events ----

	@Override
	public void connected(boolean online)
	{
		if (!online && phase != Phase.IDLE)
		{
			notice.accept("Lost the duel relay.");
			reset();
		}
		changed.run();
	}

	@Override
	public void challenge(String from, String game, Map<String, Object> data)
	{
		if (!GAME.equals(game))
		{
			return;
		}
		DuelRules theirRules = DuelRules.parse(RelayClient.str(data, "rules"));
		if (theirRules == null)
		{
			return;
		}
		if (phase != Phase.IDLE || isBlocked(from))
		{
			relay.decline(from, game, data);
			return;
		}
		opponent = from;
		rules = theirRules;
		phase = Phase.INCOMING;
		changed.run();
	}

	@Override
	public void answer(boolean accepted, String from, String game, Map<String, Object> data)
	{
		if (!GAME.equals(game) || opponent == null || !Names.same(from, opponent))
		{
			return;
		}
		if (phase == Phase.SENT)
		{
			if (!accepted)
			{
				notice.accept(from + " declined the duel.");
			}
			// Accepted: the relay pushes the record next; nothing starts here.
			reset();
		}
		else if (phase == Phase.INCOMING && !accepted)
		{
			notice.accept(from + " withdrew the challenge.");
			reset();
		}
	}

	@Override
	public void offline(String to)
	{
		if (phase == Phase.SENT && opponent != null && Names.same(to, opponent))
		{
			notice.accept(to + " is not online, or has duels turned off.");
			reset();
		}
	}

	@Override
	public void sent(String to)
	{
	}

	@Override
	public void share(String from, String game, String kind, Map<String, Object> data)
	{
	}

	@Override
	public void who(List<String> online)
	{
	}

	@Override
	public void duel(Map<String, Object> record)
	{
		ledger.update(record);
		if (phase == Phase.QUEUED)
		{
			phase = Phase.IDLE;
			queuedAt = 0;
		}
		afterLedger();
	}

	@Override
	public void sync(List<Map<String, Object>> duels, Map<String, Object> history)
	{
		ledger.sync(duels, history);
		afterLedger();
	}

	@Override
	public void queued(String queuedRules)
	{
		phase = Phase.QUEUED;
		if (queuedAt == 0)
		{
			queuedAt = System.currentTimeMillis();
		}
		changed.run();
	}

	@Override
	public void dequeued()
	{
		if (phase == Phase.QUEUED)
		{
			reset();
		}
	}

	@Override
	public void board(String key, List<Map<String, Object>> top, boolean dev)
	{
		boards.put(key, top);
		devBoards = dev;
		changed.run();
	}

	@Override
	public void ranks(String key, List<Map<String, Object>> top)
	{
		ranks.put(key, top);
		changed.run();
	}

	@Override
	public void history(Map<String, Object> history)
	{
		ledger.setHistory(history);
		changed.run();
	}

	// ---- plumbing ----

	private void afterLedger()
	{
		if (playingId != null && (ledger.get(playingId) == null || ledger.get(playingId).isDone()))
		{
			playingId = null;
			pendingPlay = null;
		}
		if (pendingPlay != null)
		{
			DuelRecord r = ledger.get(pendingPlay);
			if (r != null && r.nextGame() > 0 && r.hasSeed(r.nextGame()))
			{
				pendingPlay = null;
				ready.accept(r);
			}
		}
		changed.run();
	}

	private boolean isBlocked(String name)
	{
		Set<String> names = blockList == null ? null : blockList.get();
		if (names == null)
		{
			return false;
		}
		for (String n : names)
		{
			if (Names.same(n, name))
			{
				return true;
			}
		}
		return false;
	}

	private void reset()
	{
		phase = Phase.IDLE;
		opponent = null;
		rules = null;
		queuedAt = 0;
		changed.run();
	}

	private static Map<String, Object> rulesData(DuelRules r)
	{
		Map<String, Object> m = new HashMap<>();
		m.put("rules", r == null ? "" : r.canonical());
		return m;
	}
}

package com.trappychinchompa.duel;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Every duel the relay says I am in, plus my record. Settled duels
 * become news once; the relay does all the verifying.
 */
public final class DuelLedger
{
	private final String me;
	private final Map<String, DuelRecord> records = new LinkedHashMap<>();
	private final Set<String> announced = new HashSet<>();
	private final List<DuelRecord> fresh = new ArrayList<>();
	private Map<String, Object> history = new LinkedHashMap<>();

	public DuelLedger(String me)
	{
		this.me = me;
	}

	public String getMe()
	{
		return me;
	}

	/** The relay pushed a record (new or changed). */
	public void update(Map<String, Object> raw)
	{
		DuelRecord r = DuelRecord.from(raw, me);
		records.put(r.getId(), r);
		if (r.isDone() && announced.add(r.getId()))
		{
			fresh.add(r);
		}
	}

	/** Hello answered: the active duels and my record. Settled ones already shown stay until dismissed. */
	public void sync(List<Map<String, Object>> active, Map<String, Object> historyMap)
	{
		Map<String, DuelRecord> keep = new LinkedHashMap<>();
		for (DuelRecord r : records.values())
		{
			if (r.isDone())
			{
				keep.put(r.getId(), r);
			}
		}
		records.clear();
		records.putAll(keep);
		if (active != null)
		{
			for (Map<String, Object> raw : active)
			{
				update(raw);
			}
		}
		if (historyMap != null)
		{
			history = historyMap;
		}
	}

	public void setHistory(Map<String, Object> historyMap)
	{
		if (historyMap != null)
		{
			history = historyMap;
		}
	}

	public List<DuelRecord> duels()
	{
		return new ArrayList<>(records.values());
	}

	public DuelRecord get(String id)
	{
		return records.get(id);
	}

	public void dismiss(String id)
	{
		records.remove(id);
	}

	/** Settled since last asked, once each. */
	public List<DuelRecord> freshlySettled()
	{
		List<DuelRecord> out = new ArrayList<>(fresh);
		fresh.clear();
		return out;
	}

	// ---- my record ----

	public Map<String, Object> history()
	{
		return history;
	}

	public int getWins()
	{
		return count(history, "wins");
	}

	public int getLosses()
	{
		return count(history, "losses");
	}

	public static int count(Map<String, Object> m, String key)
	{
		Object v = m == null ? null : m.get(key);
		return v instanceof Number ? ((Number) v).intValue() : 0;
	}
}

package com.trappychinchompa.duel;

import java.util.Collections;
import java.util.List;

/** How a duel ended, as seen from one player's side. */
public final class DuelOutcome
{
	public enum Reason
	{
		WIN, FORFEIT, CHEAT, DISCONNECT, NO_CONTEST, DISPUTED, DRAW
	}

	public static final class GameLine
	{
		private final int gameIndex;
		private final int mine;
		private final int theirs;
		private final boolean suddenDeath;

		public GameLine(int gameIndex, int mine, int theirs, boolean suddenDeath)
		{
			this.gameIndex = gameIndex;
			this.mine = mine;
			this.theirs = theirs;
			this.suddenDeath = suddenDeath;
		}

		public int getGameIndex()
		{
			return gameIndex;
		}

		public int getMine()
		{
			return mine;
		}

		public int getTheirs()
		{
			return theirs;
		}

		public boolean isSuddenDeath()
		{
			return suddenDeath;
		}
	}

	private final String winner;
	private final Reason reason;
	private final List<GameLine> games;
	private final String scoreLine;

	public DuelOutcome(String winner, Reason reason, List<GameLine> games, String scoreLine)
	{
		this.winner = winner;
		this.reason = reason;
		this.games = Collections.unmodifiableList(games);
		this.scoreLine = scoreLine;
	}

	/** The winner's name, or null when nobody won (no contest, disputed). */
	public String getWinner()
	{
		return winner;
	}

	public Reason getReason()
	{
		return reason;
	}

	public List<GameLine> getGames()
	{
		return games;
	}

	public String getScoreLine()
	{
		return scoreLine;
	}
}

package com.trappychinchompa.duel;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * One duel as the relay keeps it, read from my side: who I play, which
 * game is mine to play next, which of their runs I still have to judge,
 * how long is left, and the outcome once settled.
 */
public final class DuelRecord
{
	public enum Todo
	{
		PLAY, WAIT, DONE
	}

	/** One reported run. */
	public static final class Report
	{
		private final int game;
		private final int score;
		private final List<Integer> flaps;
		private final int ticks;

		Report(int game, int score, List<Integer> flaps, int ticks)
		{
			this.game = game;
			this.score = score;
			this.flaps = Collections.unmodifiableList(flaps);
			this.ticks = ticks;
		}

		public int getGame()
		{
			return game;
		}

		public int getScore()
		{
			return score;
		}

		public List<Integer> getFlaps()
		{
			return flaps;
		}

		public int getTicks()
		{
			return ticks;
		}
	}

	private final Map<String, Object> raw;
	private final String id;
	private final String kind;
	private final DuelRules rules;
	private final String me;
	private final String opponent;
	/** Seeds by game index: only the games I have started are revealed. */
	private final Map<Integer, Long> seeds;
	private final long deadline;
	private final int stretchEnd;
	private final boolean done;
	private final String winner;
	private final String reason;
	private final List<Report> mine;
	private final List<Report> theirs;

	private DuelRecord(Map<String, Object> raw, String meName)
	{
		this.raw = raw;
		this.id = str(raw, "id");
		this.kind = str(raw, "kind");
		this.rules = DuelRules.parse(str(raw, "rules"));
		List<String> players = strings(raw.get("players"));
		String a = players.size() > 0 ? players.get(0) : "";
		String b = players.size() > 1 ? players.get(1) : "";
		boolean meIsA = Names.same(a, meName);
		this.me = meIsA ? a : b;
		this.opponent = meIsA ? b : a;
		this.seeds = new java.util.HashMap<>();
		Object seedMap = raw.get("seeds");
		if (seedMap instanceof Map)
		{
			for (Map.Entry<?, ?> e : ((Map<?, ?>) seedMap).entrySet())
			{
				try
				{
					seeds.put(Integer.parseInt(String.valueOf(e.getKey())), parseSeed(String.valueOf(e.getValue())));
				}
				catch (NumberFormatException ignored)
				{
					// A key that is not a game index: not ours.
				}
			}
		}
		this.deadline = num(raw, "deadline");
		this.stretchEnd = (int) num(raw, "stretchEnd");
		this.done = "DONE".equals(str(raw, "status"));
		Object result = raw.get("result");
		this.winner = result instanceof Map ? nullable(((Map<?, ?>) result).get("winner")) : null;
		this.reason = result instanceof Map ? nullable(((Map<?, ?>) result).get("reason")) : null;
		this.mine = reports(raw, me);
		this.theirs = reports(raw, opponent);
	}

	public static DuelRecord from(Map<String, Object> raw, String me)
	{
		return new DuelRecord(raw, me);
	}

	// ---- identity ----

	public String getId()
	{
		return id;
	}

	public boolean isCompete()
	{
		return "compete".equals(kind);
	}

	public DuelRules getRules()
	{
		return rules;
	}

	public String getMe()
	{
		return me;
	}

	public String getOpponent()
	{
		return opponent;
	}

	public long getDeadline()
	{
		return deadline;
	}

	/** When the relay settled it (0 while active). */
	public long getSettledAt()
	{
		return num(raw, "settled");
	}

	public boolean isDone()
	{
		return done;
	}

	public Map<String, Object> raw()
	{
		return raw;
	}

	// ---- what to do ----

	/** 1-based index of the game I should play next, or 0 when my stretch is in. */
	public int nextGame()
	{
		if (done || mine.size() >= stretchEnd || mine.size() >= 10)
		{
			return 0;
		}
		return mine.size() + 1;
	}

	/** The seed for a game I have started, else null (ask the relay with start). */
	public Long seed(int gameIndex)
	{
		return seeds.get(gameIndex);
	}

	public boolean hasSeed(int gameIndex)
	{
		return seeds.containsKey(gameIndex);
	}

	public Report theirReport(int gameIndex)
	{
		return gameIndex >= 1 && gameIndex <= theirs.size() ? theirs.get(gameIndex - 1) : null;
	}

	public Report myReport(int gameIndex)
	{
		return gameIndex >= 1 && gameIndex <= mine.size() ? mine.get(gameIndex - 1) : null;
	}

	public Todo todo()
	{
		if (done)
		{
			return Todo.DONE;
		}
		return nextGame() > 0 ? Todo.PLAY : Todo.WAIT;
	}

	public long timeLeft(long now)
	{
		return Math.max(0, deadline - now);
	}

	public boolean isSuddenDeath(int gameIndex)
	{
		return rules != null && gameIndex > rules.getSeries();
	}

	public String gameLabel(int gameIndex)
	{
		return isSuddenDeath(gameIndex) ? "sudden death" : "game " + gameIndex + (rules == null ? "" : " of " + rules.getSeries());
	}

	// ---- the verdict ----

	public DuelOutcome outcome()
	{
		int n = Math.min(mine.size(), theirs.size());
		Series series = new Series(rules == null ? DuelRules.parse("n-bs1") : rules);
		for (int i = 0; i < n; i++)
		{
			series.record(i + 1, mine.get(i).getScore(), theirs.get(i).getScore());
		}
		DuelOutcome.Reason r;
		switch (reason == null ? "" : reason)
		{
			case "WIN":
				r = DuelOutcome.Reason.WIN;
				break;
			case "FORFEIT":
				r = DuelOutcome.Reason.FORFEIT;
				break;
			case "CHEAT":
				r = DuelOutcome.Reason.CHEAT;
				break;
			case "TIMEOUT":
				r = DuelOutcome.Reason.DISCONNECT;
				break;
			case "DRAW":
				r = DuelOutcome.Reason.DRAW;
				break;
			default:
				r = DuelOutcome.Reason.NO_CONTEST;
		}
		return new DuelOutcome(winner, r, series.lines(), series.scoreLine());
	}

	// ---- parsing ----

	private static List<Report> reports(Map<String, Object> raw, String who)
	{
		List<Report> out = new ArrayList<>();
		Object all = raw.get("reports");
		if (!(all instanceof Map))
		{
			return out;
		}
		Object list = ((Map<?, ?>) all).get(who);
		if (!(list instanceof List))
		{
			return out;
		}
		for (Object o : (List<?>) list)
		{
			if (o instanceof Map)
			{
				Map<?, ?> m = (Map<?, ?>) o;
				List<Integer> flaps = new ArrayList<>();
				Object f = m.get("flaps");
				if (f instanceof List)
				{
					for (Object x : (List<?>) f)
					{
						flaps.add(((Number) x).intValue());
					}
				}
				out.add(new Report(((Number) m.get("game")).intValue(), ((Number) m.get("score")).intValue(),
					flaps, ((Number) m.get("ticks")).intValue()));
			}
		}
		return out;
	}

	private static List<String> strings(Object o)
	{
		List<String> out = new ArrayList<>();
		if (o instanceof List)
		{
			for (Object x : (List<?>) o)
			{
				out.add(String.valueOf(x));
			}
		}
		return out;
	}

	private static long parseSeed(String s)
	{
		try
		{
			return Long.parseLong(s.trim());
		}
		catch (NumberFormatException e)
		{
			return s.hashCode();
		}
	}

	private static String str(Map<String, Object> m, String key)
	{
		Object v = m.get(key);
		return v == null ? "" : String.valueOf(v);
	}

	private static String nullable(Object v)
	{
		return v == null ? null : String.valueOf(v);
	}

	private static long num(Map<String, Object> m, String key)
	{
		Object v = m.get(key);
		return v instanceof Number ? ((Number) v).longValue() : 0L;
	}
}

package com.trappychinchompa.duel;

/** Player-facing words for how a duel ended. ASCII only. */
public final class DuelResultText
{
	private DuelResultText()
	{
	}

	private static boolean iWon(DuelOutcome outcome, String me)
	{
		return outcome.getWinner() != null && Names.same(outcome.getWinner(), me);
	}

	/** One chatbox line: "Duel vs Zezima: you won, best 9 to 8 (Hard, best round of 3)." */
	public static String chatLine(DuelOutcome outcome, String me, String opponent, DuelRules rules)
	{
		String head = "Duel vs " + opponent + ": ";
		boolean won = iWon(outcome, me);
		switch (outcome.getReason())
		{
			case WIN:
				return head + (won ? "you won" : "you lost") + ", " + outcome.getScoreLine()
					+ " (" + rules.describe() + ").";
			case FORFEIT:
				return head + (won ? opponent + " forfeited, you win." : "you forfeited, " + opponent + " wins.");
			case CHEAT:
				return head + (won ? "their score did not check out, you win."
					: "your score did not check out, " + opponent + " wins.");
			case DISCONNECT:
				return head + (won ? opponent + " ran out of time, you win." : "you ran out of time, " + opponent + " wins.");
			case NO_CONTEST:
				return head + "no contest.";
			case DRAW:
				return head + "a draw, " + outcome.getScoreLine() + " (" + rules.describe() + ").";
			case DISPUTED:
			default:
				return head + "disputed result, no winner.";
		}
	}

	public static String headline(DuelOutcome outcome, String me)
	{
		switch (outcome.getReason())
		{
			case NO_CONTEST:
				return "NO CONTEST";
			case DISPUTED:
				return "DISPUTED";
			case DRAW:
				return "DRAW";
			default:
				return iWon(outcome, me) ? "YOU WIN!" : "YOU LOSE";
		}
	}

	/** The headline in strip case. */
	public static String headlineTitle(DuelOutcome outcome, String me)
	{
		switch (outcome.getReason())
		{
			case NO_CONTEST:
				return "No Contest";
			case DISPUTED:
				return "Disputed";
			case DRAW:
				return "Draw";
			default:
				return iWon(outcome, me) ? "You Win!" : "You Lose";
		}
	}

	/** Empty for a plain win; otherwise why it ended the way it did. */
	public static String reasonLine(DuelOutcome outcome, String me, String opponent)
	{
		boolean won = iWon(outcome, me);
		switch (outcome.getReason())
		{
			case FORFEIT:
				return won ? opponent + " forfeited" : "You forfeited";
			case CHEAT:
				return won ? "Their score did not check out" : "Your score did not check out";
			case DISCONNECT:
				return won ? opponent + " ran out of time" : "You ran out of time";
			case NO_CONTEST:
				return "Nobody showed up";
			case DISPUTED:
				return "The two clients disagree";
			case DRAW:
				return "Ten games and still level";
			case WIN:
			default:
				return "";
		}
	}
}

package com.trappychinchompa.duel;

import com.trappychinchompa.Difficulty;
import java.util.Objects;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * What a duel is played under: difficulty, how the series is scored and
 * how many games. Canonical code "<e|n|h>-<bs|av><1|3|5>", e.g. "h-bs3".
 */
public final class DuelRules
{
	public enum Metric
	{
		BEST_ROUND("bs", "best round"),
		AVERAGE("av", "average");

		private final String code;
		private final String label;

		Metric(String code, String label)
		{
			this.code = code;
			this.label = label;
		}

		public String getCode()
		{
			return code;
		}

		public String getLabel()
		{
			return label;
		}

		static Metric fromCode(String code)
		{
			for (Metric m : values())
			{
				if (m.code.equals(code))
				{
					return m;
				}
			}
			return null;
		}
	}

	public static final int[] SERIES = {1, 3, 5};
	private static final Pattern CANONICAL = Pattern.compile("^([enh])-(bs|av)([135])$");

	private final Difficulty difficulty;
	private final Metric metric;
	private final int series;

	public DuelRules(Difficulty difficulty, Metric metric, int series)
	{
		this.difficulty = Objects.requireNonNull(difficulty);
		this.metric = Objects.requireNonNull(metric);
		if (series != 1 && series != 3 && series != 5)
		{
			throw new IllegalArgumentException("series must be 1, 3 or 5");
		}
		this.series = series;
	}

	/** Null for anything outside the grammar. */
	public static DuelRules parse(String code)
	{
		if (code == null)
		{
			return null;
		}
		Matcher m = CANONICAL.matcher(code.toLowerCase());
		if (!m.matches())
		{
			return null;
		}
		Difficulty d;
		switch (m.group(1))
		{
			case "e":
				d = Difficulty.EASY;
				break;
			case "n":
				d = Difficulty.NORMAL;
				break;
			default:
				d = Difficulty.HARD;
		}
		return new DuelRules(d, Metric.fromCode(m.group(2)), m.group(3).charAt(0) - '0');
	}

	public String canonical()
	{
		return Character.toLowerCase(difficulty.name().charAt(0)) + "-" + metric.code + series;
	}

	/** "Hard, best round of 3" */
	public String describe()
	{
		String name = difficulty.name().charAt(0) + difficulty.name().substring(1).toLowerCase();
		return name + ", " + metric.label + " of " + series;
	}

	public Difficulty getDifficulty()
	{
		return difficulty;
	}

	public Metric getMetric()
	{
		return metric;
	}

	public int getSeries()
	{
		return series;
	}

	@Override
	public boolean equals(Object o)
	{
		if (!(o instanceof DuelRules))
		{
			return false;
		}
		DuelRules r = (DuelRules) o;
		return difficulty == r.difficulty && metric == r.metric && series == r.series;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(difficulty, metric, series);
	}

	@Override
	public String toString()
	{
		return canonical();
	}
}

package com.trappychinchompa.duel;

import com.trappychinchompa.Difficulty;
import com.trappychinchompa.game.FlappyGame;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Random;

/**
 * One duel game: a FlappyGame on a fixed 242x480 virtual viewport, seeded,
 * recording every flap as the tick index it fired on. The same trace
 * replayed against the same seed reproduces the same score anywhere.
 */
public final class DuelRun
{
	public static final int WIDTH = 242;
	public static final int HEIGHT = 480;
	public static final int FPS = 60;
	/** Ten minutes of ticks; hitting it ends the run where it stands. */
	public static final int MAX_TICKS = 600 * FPS;

	private final FlappyGame game;
	private final List<Integer> flapTicks = new ArrayList<>();
	private int ticks;
	private boolean capped;

	public DuelRun(long seed, DuelRules rules)
	{
		game = new FlappyGame(new Random(seed));
		game.setViewport(WIDTH, HEIGHT);
		Difficulty d = rules.getDifficulty();
		game.setDifficulty(d.getGapSize(), d.getSpeed(), d.getMaxGapStep());
	}

	public FlappyGame game()
	{
		return game;
	}

	/** A flap at the current tick; the first one launches the run. */
	public void flap()
	{
		if (ended())
		{
			return;
		}
		flapTicks.add(ticks);
		game.flap();
	}

	/** Advance one frame. After the run ends the game still animates but ticks no longer count. */
	public void tick()
	{
		if (ended())
		{
			game.tick();
			return;
		}
		game.tick();
		ticks++;
		if (ticks >= MAX_TICKS)
		{
			capped = true;
		}
	}

	public boolean ended()
	{
		return capped || game.getState() == FlappyGame.State.DEAD;
	}

	public int score()
	{
		return game.getScore();
	}

	public List<Integer> flapTicks()
	{
		return Collections.unmodifiableList(flapTicks);
	}

	public int totalTicks()
	{
		return ticks;
	}
}

package com.trappychinchompa.duel;

import java.awt.Point;

/**
 * Where the fixed 242x480 duel world sits inside the real panel:
 * letterboxed, centred, scaled. Whole and half scales are preferred once
 * the panel is at least native size so sprites stay crisp.
 */
public final class DuelViewport
{
	private final double scale;
	private final int offsetX;
	private final int offsetY;

	private DuelViewport(double scale, int offsetX, int offsetY)
	{
		this.scale = scale;
		this.offsetX = offsetX;
		this.offsetY = offsetY;
	}

	public static DuelViewport fit(int panelWidth, int panelHeight)
	{
		double s = Math.min(panelWidth / (double) DuelRun.WIDTH, panelHeight / (double) DuelRun.HEIGHT);
		if (s >= 1.0)
		{
			s = Math.floor(s * 4) / 4.0;
		}
		int ox = (int) Math.round((panelWidth - DuelRun.WIDTH * s) / 2);
		int oy = (int) Math.round((panelHeight - DuelRun.HEIGHT * s) / 2);
		return new DuelViewport(s, Math.max(0, ox), Math.max(0, oy));
	}

	public double getScale()
	{
		return scale;
	}

	public int getOffsetX()
	{
		return offsetX;
	}

	public int getOffsetY()
	{
		return offsetY;
	}

	/** A panel point in duel-world coordinates. */
	public Point toDuel(Point panelPoint)
	{
		return new Point(
			(int) Math.floor((panelPoint.x - offsetX) / scale),
			(int) Math.floor((panelPoint.y - offsetY) / scale));
	}
}

package com.trappychinchompa.duel;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

/** SHA-256 helpers for commits, channel keys and trace hashes. */
public final class Hashes
{
	private Hashes()
	{
	}

	/** The id the relay binds a name to: a SHA-256 of the RuneLite account
	 * hash under the prefix every AKAddons plugin shares, so the number
	 * itself never leaves the client and one name stays one account
	 * across plugins. The relay keys it again with its own secret. */
	public static String account(long accountHash)
	{
		return sha256Hex("akaddons:" + accountHash);
	}

	public static String sha256Hex(String text)
	{
		return sha256Hex(text.getBytes(StandardCharsets.UTF_8));
	}

	public static String sha256Hex(byte[] bytes)
	{
		return hex(sha256(bytes));
	}

	public static byte[] sha256(byte[] bytes)
	{
		try
		{
			return MessageDigest.getInstance("SHA-256").digest(bytes);
		}
		catch (NoSuchAlgorithmException e)
		{
			throw new IllegalStateException("SHA-256 missing", e);
		}
	}

	public static String hex(byte[] bytes)
	{
		StringBuilder sb = new StringBuilder(bytes.length * 2);
		for (byte b : bytes)
		{
			sb.append(Character.forDigit((b >> 4) & 0xF, 16));
			sb.append(Character.forDigit(b & 0xF, 16));
		}
		return sb.toString();
	}
}

package com.trappychinchompa.duel;

import java.util.Locale;

/** Player names as the game shows them, made comparable. */
public final class Names
{
	private Names()
	{
	}

	public static String normalise(String name)
	{
		return name == null ? "" : name.replace('\u00A0', ' ').replace('_', ' ').trim().toLowerCase(Locale.ROOT);
	}

	public static boolean same(String a, String b)
	{
		return !normalise(a).isEmpty() && normalise(a).equals(normalise(b));
	}
}

package com.trappychinchompa.duel;

import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.WebSocket;
import okhttp3.WebSocketListener;

/** The relay socket over RuneLite's OkHttp client. */
public final class OkHttpSocket implements RelayClient.Socket
{
	private final OkHttpClient http;
	private WebSocket socket;

	public OkHttpSocket(OkHttpClient http)
	{
		this.http = http;
	}

	@Override
	public void open(String url, RelayClient.SocketListener listener)
	{
		close();
		socket = http.newWebSocket(new Request.Builder().url(url).build(), new WebSocketListener()
		{
			@Override
			public void onOpen(WebSocket webSocket, Response response)
			{
				listener.onOpen();
			}

			@Override
			public void onMessage(WebSocket webSocket, String text)
			{
				listener.onText(text);
			}

			@Override
			public void onClosed(WebSocket webSocket, int code, String reason)
			{
				listener.onClosed();
			}

			@Override
			public void onFailure(WebSocket webSocket, Throwable t, Response response)
			{
				listener.onClosed();
			}
		});
	}

	@Override
	public void send(String text)
	{
		WebSocket s = socket;
		if (s != null)
		{
			s.send(text);
		}
	}

	@Override
	public void close()
	{
		WebSocket s = socket;
		socket = null;
		if (s != null)
		{
			s.close(1000, "bye");
		}
	}
}

package com.trappychinchompa.duel;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.Executor;

/**
 * One connection to the AKAddons relay: hello by display name, lobby
 * traffic (challenges, answers, shares, presence), the duel book (records,
 * reports, verdicts, compete, boards). The socket is a seam so tests
 * drive it with a fake; the plugin binds OkHttp. Every callback runs on
 * the given executor.
 */
public final class RelayClient
{
	public interface Socket
	{
		void open(String url, SocketListener listener);

		void send(String text);

		void close();
	}

	public interface SocketListener
	{
		void onOpen();

		void onText(String text);

		void onClosed();
	}

	/** Run a task later, on the same thread the callbacks use. */
	public interface Scheduler
	{
		void later(long delayMs, Runnable task);
	}

	/** What the relay tells the plugin. */
	public interface Lobby
	{
		void connected(boolean online);

		void challenge(String from, String game, Map<String, Object> data);

		void answer(boolean accepted, String from, String game, Map<String, Object> data);

		void offline(String to);

		void sent(String to);

		void share(String from, String game, String kind, Map<String, Object> data);

		void who(List<String> online);

		void duel(Map<String, Object> record);

		void sync(List<Map<String, Object>> duels, Map<String, Object> history);

		void queued(String rules);

		void dequeued();

		void board(String key, List<Map<String, Object>> top, boolean dev);

		void ranks(String key, List<Map<String, Object>> top);

		void history(Map<String, Object> history);
	}

	static final int PROTOCOL = 1;
	static final long BACKOFF_MIN_MS = 1_000;
	static final long BACKOFF_MAX_MS = 30_000;
	private static final Type MAP = new TypeToken<Map<String, Object>>()
	{
	}.getType();

	private final String url;
	private final Socket socket;
	private final Executor callbacks;
	private final Scheduler scheduler;
	private final Lobby lobby;
	/** The client's Gson (the hub forbids fresh instances). */
	private final Gson gson;

	private String name;
	private String game;
	private String account;
	private boolean hidden;
	private boolean dev;
	private boolean enabled;
	private boolean open;
	private boolean online;
	private long backoff = BACKOFF_MIN_MS;
	/** Bumped on every dial so a stale socket's late events are ignored. */
	private int generation;

	public RelayClient(String url, Socket socket, Executor callbacks, Scheduler scheduler, Lobby lobby, Gson gson)
	{
		this.gson = gson;
		this.url = url;
		this.socket = socket;
		this.callbacks = callbacks;
		this.scheduler = scheduler;
		this.lobby = lobby;
	}

	public String getName()
	{
		return name;
	}

	public boolean isOnline()
	{
		return online;
	}

	public boolean isEnabled()
	{
		return enabled;
	}

	/** Start (or restart under a new name) and keep reconnecting until disconnect(). */
	/** dev: a developer-mode client; its games pair freely and count for nothing. */
	public void connect(String displayName, String gameId, String accountId, boolean hideFromBoards, boolean developerMode)
	{
		name = displayName;
		game = gameId;
		account = accountId;
		hidden = hideFromBoards;
		dev = developerMode;
		enabled = true;
		backoff = BACKOFF_MIN_MS;
		if (open)
		{
			socket.close();
			open = false;
		}
		dial();
	}

	public void disconnect()
	{
		enabled = false;
		name = null;
		online = false;
		if (open)
		{
			open = false;
			socket.close();
		}
	}

	/** The scheduled reconnect fires. */
	public void retry()
	{
		if (enabled && !open)
		{
			dial();
		}
	}

	private void dial()
	{
		open = true;
		final int gen = ++generation;
		socket.open(url, new SocketListener()
		{
			@Override
			public void onOpen()
			{
				callbacks.execute(() ->
				{
					if (gen == generation)
					{
						opened();
					}
				});
			}

			@Override
			public void onText(String text)
			{
				callbacks.execute(() ->
				{
					if (gen == generation)
					{
						received(text);
					}
				});
			}

			@Override
			public void onClosed()
			{
				callbacks.execute(() ->
				{
					if (gen == generation)
					{
						closed();
					}
				});
			}
		});
	}

	// ---- lobby traffic ----

	public void challenge(String to, String game, Map<String, Object> data)
	{
		send(msg("challenge", "to", to, "game", game, "data", data));
	}

	public void accept(String to, String game, Map<String, Object> data)
	{
		send(msg("accept", "to", to, "game", game, "data", data));
	}

	public void decline(String to, String game, Map<String, Object> data)
	{
		send(msg("decline", "to", to, "game", game, "data", data));
	}

	public void share(String to, String game, String kind, Map<String, Object> data)
	{
		send(msg("send", "to", to, "game", game, "kind", kind, "data", data));
	}

	public void who(List<String> names)
	{
		send(msg("who", "names", new ArrayList<>(names)));
	}

	// ---- the duel book ----

	public void report(String duel, int gameIndex, int score, List<Integer> flaps, int ticks)
	{
		send(msg("report", "duel", duel, "game", gameIndex, "score", score, "flaps", new ArrayList<>(flaps), "ticks", ticks));
	}

	/** Play pressed: ask for this game's seed and start its clock. */
	public void start(String duel, int gameIndex)
	{
		send(msg("start", "duel", duel, "game", gameIndex));
	}

	public void concede(String duel)
	{
		send(msg("concede", "duel", duel));
	}

	public void touch(String duel)
	{
		send(msg("touch", "duel", duel));
	}

	public void compete(String game, String rules)
	{
		send(msg("compete", "game", game, "rules", rules));
	}

	public void uncompete()
	{
		send(msg("uncompete"));
	}

	public void board(String game, String key)
	{
		send(msg("board", "game", game, "key", key));
	}

	public void ranks(String game, String key)
	{
		send(msg("ranks", "game", game, "key", key));
	}

	public void history(String game)
	{
		send(msg("history", "game", game));
	}

	// ---- socket events (already on the callback thread) ----

	private void opened()
	{
		if (!enabled || !open)
		{
			return;
		}
		send(msg("hello", "name", name, "v", PROTOCOL, "game", game, "account", account, "hidden", hidden, "dev", dev));
	}

	private void closed()
	{
		boolean wasOpen = open;
		open = false;
		online = false;
		if (!enabled)
		{
			return;
		}
		if (wasOpen)
		{
			lobby.connected(false);
		}
		long delay = backoff;
		backoff = Math.min(BACKOFF_MAX_MS, backoff * 2);
		scheduler.later(delay, this::retry);
	}

	@SuppressWarnings("unchecked")
	private void received(String text)
	{
		Map<String, Object> m;
		try
		{
			m = gson.fromJson(text, MAP);
		}
		catch (RuntimeException e)
		{
			return;
		}
		if (m == null || !(m.get("t") instanceof String))
		{
			return;
		}
		String t = (String) m.get("t");
		String from = str(m, "from");
		String gameId = str(m, "game");
		switch (t)
		{
			case "welcome":
				online = true;
				backoff = BACKOFF_MIN_MS;
				lobby.connected(true);
				break;
			case "challenge":
				lobby.challenge(from, gameId, data(m));
				break;
			case "accept":
				lobby.answer(true, from, gameId, data(m));
				break;
			case "decline":
				lobby.answer(false, from, gameId, data(m));
				break;
			case "offline":
				lobby.offline(str(m, "to"));
				break;
			case "sent":
				lobby.sent(str(m, "to"));
				break;
			case "send":
				lobby.share(from, gameId, str(m, "kind"), data(m));
				break;
			case "who":
				lobby.who(strings(m.get("online")));
				break;
			case "duel":
				if (m.get("record") instanceof Map)
				{
					lobby.duel((Map<String, Object>) m.get("record"));
				}
				break;
			case "sync":
				lobby.sync(maps(m.get("duels")), m.get("history") instanceof Map ? (Map<String, Object>) m.get("history") : null);
				break;
			case "queued":
				lobby.queued(str(m, "rules"));
				break;
			case "dequeued":
				lobby.dequeued();
				break;
			case "board":
				lobby.board(str(m, "key"), maps(m.get("top")), Boolean.TRUE.equals(m.get("dev")));
				break;
			case "ranks":
				lobby.ranks(str(m, "key"), maps(m.get("top")));
				break;
			case "history":
				lobby.history(m);
				break;
			default:
				break;
		}
	}

	// ---- plumbing ----

	private void send(Map<String, Object> m)
	{
		if (open)
		{
			socket.send(gson.toJson(m));
		}
	}

	private static Map<String, Object> msg(String type, Object... kv)
	{
		Map<String, Object> m = new HashMap<>();
		m.put("t", type);
		for (int i = 0; i < kv.length; i += 2)
		{
			m.put((String) kv[i], kv[i + 1]);
		}
		return m;
	}

	static String str(Map<String, Object> m, String key)
	{
		Object v = m.get(key);
		return v == null ? "" : v.toString();
	}

	@SuppressWarnings("unchecked")
	static Map<String, Object> data(Map<String, Object> m)
	{
		Object d = m.get("data");
		return d instanceof Map ? (Map<String, Object>) d : new HashMap<>();
	}

	@SuppressWarnings("unchecked")
	static List<Map<String, Object>> maps(Object o)
	{
		List<Map<String, Object>> out = new ArrayList<>();
		if (o instanceof List)
		{
			for (Object x : (List<?>) o)
			{
				if (x instanceof Map)
				{
					out.add((Map<String, Object>) x);
				}
			}
		}
		return out;
	}

	static List<String> strings(Object o)
	{
		List<String> out = new ArrayList<>();
		if (o instanceof List)
		{
			for (Object x : (List<?>) o)
			{
				out.add(String.valueOf(x));
			}
		}
		return out;
	}
}

package com.trappychinchompa.duel;

import java.util.ArrayList;
import java.util.List;

/**
 * Series bookkeeping: every game is played, the metric is aggregate, and
 * a dead-even aggregate goes to sudden death one game at a time.
 */
public final class Series
{
	private final DuelRules rules;
	private final List<DuelOutcome.GameLine> lines = new ArrayList<>();

	public Series(DuelRules rules)
	{
		this.rules = rules;
	}

	public DuelRules getRules()
	{
		return rules;
	}

	public void record(int gameIndex, int mine, int theirs)
	{
		lines.add(new DuelOutcome.GameLine(gameIndex, mine, theirs, gameIndex > rules.getSeries()));
	}

	/** The recorded line for a game, or a prospective unplayed one. */
	public DuelOutcome.GameLine lineFor(int gameIndex)
	{
		for (DuelOutcome.GameLine l : lines)
		{
			if (l.getGameIndex() == gameIndex)
			{
				return l;
			}
		}
		return new DuelOutcome.GameLine(gameIndex, 0, 0, gameIndex > rules.getSeries());
	}

	public List<DuelOutcome.GameLine> lines()
	{
		return new ArrayList<>(lines);
	}

	public int nextGameIndex()
	{
		return lines.size() + 1;
	}

	/** Positive when my side leads, negative when theirs does, zero when even. A sudden-death game decides on its own. */
	public int compare()
	{
		if (lines.size() > rules.getSeries())
		{
			DuelOutcome.GameLine last = lines.get(lines.size() - 1);
			return Integer.compare(last.getMine(), last.getTheirs());
		}
		return Integer.compare(aggregate(true), aggregate(false));
	}

	public boolean complete()
	{
		return lines.size() >= rules.getSeries() && compare() != 0;
	}

	private int aggregate(boolean mine)
	{
		int best = 0;
		int sum = 0;
		for (DuelOutcome.GameLine l : lines.subList(0, Math.min(lines.size(), rules.getSeries())))
		{
			int s = mine ? l.getMine() : l.getTheirs();
			best = Math.max(best, s);
			sum += s;
		}
		return rules.getMetric() == DuelRules.Metric.BEST_ROUND ? best : sum;
	}

	/** "best 9 to 8" or "total 16 to 24", my side first. */
	public String scoreLine()
	{
		String label = rules.getMetric() == DuelRules.Metric.BEST_ROUND ? "best" : "total";
		String line = label + " " + aggregate(true) + " to " + aggregate(false);
		if (lines.size() > rules.getSeries())
		{
			DuelOutcome.GameLine last = lines.get(lines.size() - 1);
			line += ", sudden death " + last.getMine() + " to " + last.getTheirs();
		}
		return line;
	}
}

package com.trappychinchompa.game;

import java.util.Set;

/**
 * Backdrop zones, unlocked by Anti-hunter level - plus one achievement-gated
 * mystery (its id matched against the achievement catalog by a drift-guard
 * test, since this package cannot depend on it). Rendering (palettes,
 * skylines) lives in the canvas; this is just the unlock ladder, kept
 * headless so it can be tested.
 *
 * Enum order is ladder order; Prifddinas is the level-99 capstone.
 */
public enum BackgroundTheme
{
	FELDIP_MARSH(1),
	LUMBRIDGE(10),
	VARROCK(20),
	AL_KHARID(30),
	MORYTANIA(40),
	ARDOUGNE(50),
	KOUREND(60),
	FREMENNIK(70),
	VARLAMORE(80),
	WILDERNESS(90),
	PRIFDDINAS(99),
	/** Mystery reward: clear 250 poles on Easy. Pure chaos. */
	PANDEMONIUM(Integer.MAX_VALUE, "score_EASY_250"),
	/** Mystery reward: a 50x20 streak on Normal OR Hard. */
	INFERNO(Integer.MAX_VALUE, "streak_NORMAL_50x20", "streak_HARD_50x20");

	private final int unlockLevel;
	/** Achievements gating this zone (ANY earns it), empty for level zones. */
	private final String[] unlockAchievementIds;

	BackgroundTheme(int unlockLevel, String... unlockAchievementIds)
	{
		this.unlockLevel = unlockLevel;
		this.unlockAchievementIds = unlockAchievementIds;
	}

	public int getUnlockLevel()
	{
		return unlockLevel;
	}

	public boolean isAchievementGated()
	{
		return unlockAchievementIds.length > 0;
	}

	/** The achievements gating this zone; empty for level-based zones. */
	public String[] getUnlockAchievementIds()
	{
		return unlockAchievementIds.clone();
	}

	/** The full check: level threshold, or ANY of the gating achievements. */
	public boolean isUnlocked(int level, Set<String> earnedAchievements)
	{
		if (isAchievementGated())
		{
			for (String id : unlockAchievementIds)
			{
				if (earnedAchievements.contains(id))
				{
					return true;
				}
			}
			return false;
		}
		return level >= unlockLevel;
	}

	/** The best zone available; FELDIP_MARSH is always open. */
	public static BackgroundTheme highestUnlocked(int level, Set<String> earnedAchievements)
	{
		BackgroundTheme best = FELDIP_MARSH;
		for (BackgroundTheme theme : values())
		{
			if (theme.isUnlocked(level, earnedAchievements))
			{
				best = theme;
			}
		}
		return best;
	}

	/**
	 * The most exciting zone newly unlocked by a level-before -> level-after
	 * jump, or null. Achievement-gated zones announce through their
	 * achievements instead.
	 */
	public static BackgroundTheme newlyUnlocked(int levelBefore, int levelAfter)
	{
		BackgroundTheme newest = null;
		for (BackgroundTheme theme : values())
		{
			if (!theme.isAchievementGated()
				&& theme.unlockLevel > levelBefore && theme.unlockLevel <= levelAfter)
			{
				newest = theme;
			}
		}
		return newest;
	}
}

package com.trappychinchompa.game;

/**
 * One box-trap tower pair: stacked traps from the ceiling and the marsh with
 * a gap the chinchompa must thread. Pure data; geometry (gap size, tower
 * width) lives on {@link FlappyGame}.
 */
public class BoxTrap
{
	private double x;
	private final int gapCenter;
	private boolean scored;

	BoxTrap(double x, int gapCenter)
	{
		this.x = x;
		this.gapCenter = gapCenter;
	}

	public double getX()
	{
		return x;
	}

	public int getGapCenter()
	{
		return gapCenter;
	}

	public boolean isScored()
	{
		return scored;
	}

	void advance(double dx)
	{
		x -= dx;
	}

	void markScored()
	{
		scored = true;
	}
}

package com.trappychinchompa.game;

import java.util.Set;
import net.runelite.api.gameval.ItemID;

/**
 * Playable critters. Most unlock by HIGH SCORE - your best run is your
 * wardrobe; the last two are achievement-gated trophies (ids matched
 * against the achievement catalog by a drift-guard test, since this
 * package cannot depend on it). Each is a real in-game item whose sprite
 * is loaded at runtime from the player's own client via ItemManager.
 *
 * Enum order is ladder order for the score-based ranks.
 */
public enum ChinSkin
{
	/** The plugin's own mascot, free from the start - original art bundled
	 * as a resource, the one critter that isn't a game item. */
	PIXEL_CHIN(-1, "chin_sprite.png", 0, null, null, false),
	GREY_CHINCHOMPA(ItemID.CHINCHOMPA_CAPTURED, null, 10, null, null, false),
	RED_CHINCHOMPA(ItemID.CHINCHOMPA_BIG_CAPTURED, null, 20, null, null, false),
	BLACK_CHINCHOMPA(ItemID.CHINCHOMPA_BLACK, null, 40, null, null, false),
	EGG(ItemID.EGG, null, 60, null, null, true),
	CHOMPY_BIRD(ItemID.CHOMPY_BIRD_OBJ, null, 80, null, null, true),
	RUBBER_CHICKEN(ItemID.RUBBER_CHICKEN, null, 100, null, null, true),
	/** The monument to wasted effort: clear 100 traps on Easy. */
	CABBAGE(ItemID.CABBAGE, null, Integer.MAX_VALUE, "score_EASY_100", null, true),
	/** Mystery reward: clear 250 traps on Normal. */
	VORKI(ItemID.VORKATHPET, null, Integer.MAX_VALUE, "score_NORMAL_250", null, true),
	/** Cross-plugin easter egg: Loadie, Loadout Lab's bottle mascot,
	 * unlocked by having Loadout Lab installed. Its art, bundled by its
	 * author. */
	LAB_MASCOT(-1, "lab_mascot.png", Integer.MAX_VALUE, "loadout_lab", "Loadie", true),
	/** The prestige mount and final flex: clear 100 traps on Hard. (The
	 * sprite is the pet item, but it flies under the boss's famous name.) */
	TZTOK_JAD(ItemID.JAD_PET, null, Integer.MAX_VALUE, "score_HARD_100", "TzTok-Jad", true);

	private final int itemId;
	/** Bundled-resource sprite name, or null for item-sprite critters. */
	private final String resourceName;
	private final int unlockHighScore;
	private final String unlockAchievementId;
	/** Exact display styling where titleCase of the name won't do. */
	private final String displayName;
	/** Everything past the chinchompas is a sealed ?????? until earned. */
	private final boolean mysteryReward;

	ChinSkin(int itemId, String resourceName, int unlockHighScore, String unlockAchievementId,
		String displayName, boolean mysteryReward)
	{
		this.itemId = itemId;
		this.resourceName = resourceName;
		this.unlockHighScore = unlockHighScore;
		this.unlockAchievementId = unlockAchievementId;
		this.displayName = displayName;
		this.mysteryReward = mysteryReward;
	}

	public String getResourceName()
	{
		return resourceName;
	}

	public boolean isMysteryReward()
	{
		return mysteryReward;
	}

	/** The styled display name, or null to fall back to titleCase. */
	public String getDisplayName()
	{
		return displayName;
	}

	public int getItemId()
	{
		return itemId;
	}

	public int getUnlockHighScore()
	{
		return unlockHighScore;
	}

	/** The achievement gating this skin, or null for score-based ranks. */
	public String getUnlockAchievementId()
	{
		return unlockAchievementId;
	}

	/** The full check: score threshold or earned achievement. */
	public boolean isUnlocked(int highScore, Set<String> earnedAchievements)
	{
		if (unlockAchievementId != null)
		{
			return earnedAchievements.contains(unlockAchievementId);
		}
		return highScore >= unlockHighScore;
	}

	/** The newest unlocked critter; the pixel chin is always open. */
	public static ChinSkin highestUnlocked(int highScore, Set<String> earnedAchievements)
	{
		ChinSkin best = PIXEL_CHIN;
		for (ChinSkin skin : values())
		{
			if (skin.isUnlocked(highScore, earnedAchievements))
			{
				best = skin;
			}
		}
		return best;
	}

	/**
	 * The newest score-ranked critter unlocked by pushing the high score
	 * from before to after, or null. Achievement-gated skins announce
	 * through their achievements instead.
	 */
	public static ChinSkin newlyUnlocked(int highBefore, int highAfter)
	{
		ChinSkin newest = null;
		for (ChinSkin skin : values())
		{
			if (skin.unlockAchievementId == null
				&& skin.unlockHighScore > highBefore && skin.unlockHighScore <= highAfter)
			{
				newest = skin;
			}
		}
		return newest;
	}
}

package com.trappychinchompa.game;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Random;

/**
 * The whole game, headless: a fixed-timestep state machine with no Swing or
 * RuneLite imports so every rule is unit-testable. The canvas calls
 * {@link #tick()} once per frame and renders whatever the getters expose.
 *
 * States: READY (chinchompa bobbing, waiting for the first flap) -> RUNNING
 * (physics + trap towers + scoring) -> DEAD (world frozen while the poor
 * chin detonates; a flap after a short cooldown returns to READY).
 */
public class FlappyGame
{
	public enum State
	{
		READY, RUNNING, DEAD
	}

	public enum DeathCause
	{
		TRAP, GROUND
	}

	/** Chinchompa centre is pinned at this x; the world scrolls past it. */
	public static final int CHIN_X = 60;
	/** Collision half-extents - deliberately smaller than the drawn sprite. */
	public static final int CHIN_HALF_W = 13;
	public static final int CHIN_HALF_H = 10;
	public static final double GRAVITY = 0.35;
	public static final double FLAP_VELOCITY = -6.2;
	public static final double MAX_FALL_SPEED = 9.0;
	/** Height of the marsh strip at the bottom; landing on it ends the run. */
	public static final int GROUND_HEIGHT = 48;
	public static final int TRAP_WIDTH = 44;
	/** Horizontal distance between successive trap-tower left edges. */
	public static final int TRAP_SPACING = 150;
	/** Minimum distance from a gap edge to the ceiling / marsh. */
	public static final int GAP_MARGIN = 28;
	/**
	 * Gaps roll inside a band of this height centred in the play area, so a
	 * taller panel widens the scenery, not the vertical spread between gaps.
	 * 376 reproduces the spread of the ~480px design-height panel exactly
	 * (432 play height minus both margins); shorter panels are unaffected.
	 */
	public static final int GAP_BAND_HEIGHT = 376;
	/** Ticks after death before a flap may reset to READY (misclick guard). */
	public static final int RESTART_COOLDOWN_TICKS = 24;

	private final Random rng;
	private final List<BoxTrap> traps = new ArrayList<>();

	private State state = State.READY;
	private DeathCause deathCause;
	private int width = 242;
	private int height = 480;
	private int gapSize = 110;
	private double speed = 1.9;
	/** Max vertical travel of the gap centre between consecutive traps. */
	private int maxGapStep = GAP_BAND_HEIGHT;
	/** Previous trap's gap centre, or -1 when the next roll is free. */
	private int lastGapCenter = -1;

	private int readyTicks;
	private double chinY = playFloor() / 2.0;
	private double chinVy;
	private int score;
	private int deadTicks;
	/** Dev sandbox: traps stop killing; only the marsh ends the run. */
	private boolean trapInvincible;

	public FlappyGame(Random rng)
	{
		this.rng = rng;
	}

	public void setViewport(int width, int height)
	{
		if (width <= 0 || height <= 0)
		{
			return;
		}
		this.width = width;
		this.height = height;
		if (state == State.READY)
		{
			chinY = playFloor() / 2.0;
		}
	}

	public void setDifficulty(int gapSize, double speed, int maxGapStep)
	{
		this.gapSize = gapSize;
		this.speed = speed;
		this.maxGapStep = maxGapStep;
	}

	public void setTrapInvincible(boolean trapInvincible)
	{
		this.trapInvincible = trapInvincible;
	}

	public boolean isTrapInvincible()
	{
		return trapInvincible;
	}

	/** Flap - and drive the READY -> RUNNING -> DEAD -> READY cycle. */
	public void flap()
	{
		switch (state)
		{
			case READY:
				startRun();
				break;
			case RUNNING:
				chinVy = FLAP_VELOCITY;
				break;
			case DEAD:
				if (canRestart())
				{
					// Respawn to a clean field: no towers, chin bobbing
					// mid-air, exactly like the first launch.
					state = State.READY;
					readyTicks = 0;
					chinY = playFloor() / 2.0;
					chinVy = 0;
					traps.clear();
				}
				break;
		}
	}

	/** Advance exactly one frame. */
	public void tick()
	{
		switch (state)
		{
			case READY:
				readyTicks++;
				// StrictMath: the bob height seeds the launch height, and duels replay it on other machines.
				chinY = playFloor() / 2.0 + StrictMath.sin(readyTicks * 0.09) * 5.0;
				break;
			case RUNNING:
				stepPhysics();
				stepTraps();
				checkCollisions();
				break;
			case DEAD:
				deadTicks++;
				// What's left of the chin drifts down onto the marsh.
				if (chinY + CHIN_HALF_H < playFloor())
				{
					chinVy = Math.min(chinVy + GRAVITY, MAX_FALL_SPEED);
					chinY = Math.min(chinY + chinVy, playFloor() - CHIN_HALF_H);
				}
				break;
		}
	}

	private void startRun()
	{
		state = State.RUNNING;
		deathCause = null;
		traps.clear();
		lastGapCenter = -1;
		score = 0;
		deadTicks = 0;
		chinVy = FLAP_VELOCITY;
	}

	private void stepPhysics()
	{
		chinVy = Math.min(chinVy + GRAVITY, MAX_FALL_SPEED);
		chinY += chinVy;
		// The canopy bumps, it doesn't kill.
		if (chinY < CHIN_HALF_H)
		{
			chinY = CHIN_HALF_H;
			chinVy = 0;
		}
	}

	private void stepTraps()
	{
		for (BoxTrap trap : traps)
		{
			trap.advance(speed);
		}
		traps.removeIf(t -> t.getX() + TRAP_WIDTH < 0);

		BoxTrap last = traps.isEmpty() ? null : traps.get(traps.size() - 1);
		if (last == null || last.getX() <= width - TRAP_SPACING)
		{
			traps.add(new BoxTrap(width, rollGapCenter()));
		}

		for (BoxTrap trap : traps)
		{
			if (!trap.isScored() && trap.getX() + TRAP_WIDTH < CHIN_X)
			{
				trap.markScored();
				score++;
			}
		}
	}

	private int rollGapCenter()
	{
		final int half = gapSize / 2;
		final int mid = playFloor() / 2;
		int lo = GAP_MARGIN + half;
		int hi = playFloor() - GAP_MARGIN - half;
		// Clamp to the fixed-height band around the middle: consistent gap
		// spacing no matter how tall the panel is stretched.
		lo = Math.max(lo, mid - GAP_BAND_HEIGHT / 2 + half);
		hi = Math.min(hi, mid + GAP_BAND_HEIGHT / 2 - half);
		if (hi <= lo)
		{
			// Viewport too small for margins - centre the gap and carry on.
			return mid;
		}
		if (lastGapCenter >= 0)
		{
			// Each gap stays reachable: the centre may travel at most
			// maxGapStep from the previous trap's.
			final int anchor = Math.max(lo, Math.min(hi, lastGapCenter));
			lo = Math.max(lo, anchor - maxGapStep);
			hi = Math.min(hi, anchor + maxGapStep);
		}
		lastGapCenter = lo + rng.nextInt(hi - lo + 1);
		return lastGapCenter;
	}

	private void checkCollisions()
	{
		if (chinY + CHIN_HALF_H >= playFloor())
		{
			chinY = playFloor() - CHIN_HALF_H;
			die(DeathCause.GROUND);
			return;
		}
		if (trapInvincible)
		{
			return;
		}
		for (BoxTrap trap : traps)
		{
			boolean xOverlap = trap.getX() < CHIN_X + CHIN_HALF_W
				&& trap.getX() + TRAP_WIDTH > CHIN_X - CHIN_HALF_W;
			if (!xOverlap)
			{
				continue;
			}
			int gapTop = trap.getGapCenter() - gapSize / 2;
			int gapBottom = trap.getGapCenter() + gapSize / 2;
			if (chinY - CHIN_HALF_H < gapTop || chinY + CHIN_HALF_H > gapBottom)
			{
				die(DeathCause.TRAP);
				return;
			}
		}
	}

	private void die(DeathCause cause)
	{
		state = State.DEAD;
		deathCause = cause;
		deadTicks = 0;
		chinVy = 0;
	}

	private int playFloor()
	{
		return height - GROUND_HEIGHT;
	}

	public State getState()
	{
		return state;
	}

	/** Why the last run ended; null until the first death. */
	public DeathCause getDeathCause()
	{
		return deathCause;
	}

	public int getScore()
	{
		return score;
	}

	public double getChinY()
	{
		return chinY;
	}

	public double getChinVy()
	{
		return chinVy;
	}

	public int getGapSize()
	{
		return gapSize;
	}

	public double getSpeed()
	{
		return speed;
	}

	public int getTicksSinceDeath()
	{
		return deadTicks;
	}

	public boolean canRestart()
	{
		return state == State.DEAD && deadTicks >= RESTART_COOLDOWN_TICKS;
	}

	/** Whether the dead chin has finished tumbling onto the marsh. */
	public boolean isSettled()
	{
		return state == State.DEAD && chinY + CHIN_HALF_H >= playFloor();
	}

	public List<BoxTrap> getTraps()
	{
		return Collections.unmodifiableList(traps);
	}

	/** Test seam: place a trap tower exactly where a scenario needs it. */
	void injectTrap(double x, int gapCenter)
	{
		traps.add(new BoxTrap(x, gapCenter));
	}

	/**
	 * Anti-hunter xp for the nth pole of a run (1-based), in tenths:
	 * +5 for the first, then +10 more each - +5, +15, +25, ...
	 * Difficulty scales and totals these per run.
	 */
	public static long xpTenthsForPole(int pole)
	{
		if (pole < 1)
		{
			return 0;
		}
		return 100L * pole - 50L;
	}
}

package com.trappychinchompa.game;

import net.runelite.api.Experience;

/**
 * Anti-hunter levelling: thin wrappers over the client's canonical OSRS
 * experience curve ({@link Experience}), clamped to real levels.
 *
 * XP is tracked in TENTHS of a point (like the game client does internally)
 * so fractional awards stay exact.
 */
public final class HunterXp
{
	public static final int MAX_LEVEL = Experience.MAX_REAL_LEVEL;

	private HunterXp()
	{
	}

	/** Whole experience points required to be the given level (1-99). */
	public static int xpForLevel(int level)
	{
		return Experience.getXpForLevel(level);
	}

	/** The level this much Anti-hunter xp (in tenths) amounts to. */
	public static int levelForXpTenths(long xpTenths)
	{
		final long xp = Math.max(0, xpTenths) / 10;
		// The API keeps counting into virtual levels; Anti-hunter caps at 99.
		return Math.min(MAX_LEVEL, Experience.getLevelForXp((int) Math.min(xp, Integer.MAX_VALUE)));
	}
}

package com.trappychinchompa.ui;

import com.trappychinchompa.Achievement;
import com.trappychinchompa.TrappyChinchompaPlugin;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.util.Set;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * The full achievement list: a real scrollable Swing view (83 rows is far
 * past what the drawn canvas cards can carry). Earned rows glow, locked
 * rows grey out, reward attributions show on the rows that carry them.
 * Rebuilt on every open so earned state is always fresh.
 */
class AchievementsPanel extends JPanel
{
	// Earned/reward/debug colours come from GameCanvas so the brand language
	// cannot drift between the game and this list.
	private static final Color EARNED = GameCanvas.TEXT_YELLOW;
	private static final Color REWARD = GameCanvas.TEXT_ORANGE;
	private static final Color DEBUG_RED = GameCanvas.DEBUG_RED;
	private static final Color LOCKED = new Color(0x8a, 0x8a, 0x8a);
	private static final Color DESC = new Color(0xb0, 0xb0, 0xb0);
	private static final Color DESC_LOCKED = new Color(0x6a, 0x6a, 0x6a);

	private final TrappyChinchompaPlugin plugin;
	private final JPanel list = new JPanel();
	private final JLabel counter = new JLabel();

	AchievementsPanel(TrappyChinchompaPlugin plugin, Runnable onBack)
	{
		this.plugin = plugin;
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		final JPanel header = new JPanel(new BorderLayout());
		header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		header.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
		final JButton back = new JButton("Back");
		back.setFocusable(false);
		back.addActionListener(e -> onBack.run());
		counter.setFont(FontManager.getRunescapeBoldFont());
		counter.setForeground(Color.WHITE);
		header.add(back, BorderLayout.WEST);
		header.add(counter, BorderLayout.EAST);
		add(header, BorderLayout.NORTH);

		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setBackground(ColorScheme.DARK_GRAY_COLOR);
		final JPanel north = new JPanel(new BorderLayout());
		north.setBackground(ColorScheme.DARK_GRAY_COLOR);
		north.add(list, BorderLayout.NORTH);
		final JScrollPane scroll = new JScrollPane(north);
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(24);
		scroll.setBorder(null);
		add(scroll, BorderLayout.CENTER);
	}

	/** Rebuild all rows against the current earned set. */
	void refresh()
	{
		final Set<String> earned = plugin.loadEarnedAchievements();
		final Set<String> debug = plugin.loadDebugAchievements();
		counter.setText(earned.size() + " / " + Achievement.ALL.size());
		list.removeAll();
		String category = null;
		for (Achievement a : Achievement.ALL)
		{
			if (!a.getCategory().equals(category))
			{
				category = a.getCategory();
				list.add(categoryHeader(category));
			}
			list.add(row(a, earned.contains(a.getId()), debug.contains(a.getId())));
		}
		list.revalidate();
		list.repaint();
	}

	private Component categoryHeader(String category)
	{
		final JLabel label = new JLabel(category);
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(Color.WHITE);
		label.setBorder(BorderFactory.createEmptyBorder(10, 8, 2, 8));
		final JPanel wrap = new JPanel(new BorderLayout());
		wrap.setBackground(ColorScheme.DARK_GRAY_COLOR);
		wrap.add(label, BorderLayout.WEST);
		wrap.setAlignmentX(LEFT_ALIGNMENT);
		return wrap;
	}

	private Component row(Achievement a, boolean earned, boolean debugEarned)
	{
		final JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.Y_AXIS));
		row.setBackground(earned ? ColorScheme.DARKER_GRAY_COLOR : ColorScheme.DARK_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(4, 10, 4, 8));
		row.setAlignmentX(LEFT_ALIGNMENT);

		final Box nameLine = Box.createHorizontalBox();
		final JLabel name = new JLabel(a.getNameDisplay(earned));
		name.setFont(FontManager.getRunescapeFont());
		name.setForeground(earned ? EARNED : LOCKED);
		nameLine.add(name);
		if (earned && debugEarned)
		{
			// The anti-cheat brand: earned with dev unlocks on, marked forever.
			final JLabel brand = new JLabel("  DEBUG");
			brand.setFont(FontManager.getRunescapeSmallFont());
			brand.setForeground(DEBUG_RED);
			nameLine.add(brand);
		}
		nameLine.setAlignmentX(LEFT_ALIGNMENT);
		row.add(nameLine);

		final JLabel desc = new JLabel(a.getDescriptionDisplay(earned));
		desc.setFont(FontManager.getRunescapeSmallFont());
		desc.setForeground(earned ? DESC : DESC_LOCKED);
		row.add(desc);

		if (a.getRewardDisplay(earned) != null)
		{
			final JLabel reward = new JLabel(a.getRewardDisplay(earned));
			reward.setFont(FontManager.getRunescapeSmallFont());
			reward.setForeground(earned ? REWARD : DESC_LOCKED);
			row.add(reward);
		}
		row.add(Box.createVerticalStrut(2));
		return row;
	}
}

package com.trappychinchompa.ui;

import com.trappychinchompa.Difficulty;
import com.trappychinchompa.duel.DuelCommand;
import com.trappychinchompa.duel.DuelController;
