package com.trappychinchompa.duel;

import com.trappychinchompa.Difficulty;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class DuelCommandTest
{
	private static DuelCommand parse(String line)
	{
		return DuelCommand.parse(line.isEmpty() ? new String[0] : line.split(" "), Difficulty.HARD);
	}

	@Test
	@DisplayName("::duel <player> trappy [games] [style] [difficulty] builds the rules, defaults filled in")
	void challenges()
	{
		DuelCommand c = parse("testpurr trappy 3 best");
		assertEquals(DuelCommand.Kind.CHALLENGE, c.getKind());
		assertEquals("testpurr", c.getPlayer());
		assertEquals("h-bs3", c.getRules().canonical());

		assertEquals("e-av5", parse("test_purr tc 5 avg easy").getRules().canonical());
		assertEquals("test purr", parse("test_purr tc 5 avg easy").getPlayer());
		assertEquals("h-bs3", parse("zezima chin").getRules().canonical());
		assertEquals("n-av1", parse("zezima trappy normal average 1").getRules().canonical());
		assertEquals("h-bs5", parse("zezima Trappy 5").getRules().canonical());
	}

	@Test
	@DisplayName("a game token for another plugin is not ours; a missing one is a usage error")
	void gameToken()
	{
		assertEquals(DuelCommand.Kind.NOT_OURS, parse("zezima loadoutlab 3").getKind());
		assertEquals(DuelCommand.Kind.USAGE, parse("zezima").getKind());
		assertEquals(DuelCommand.Kind.USAGE, parse("zezima 3 best").getKind());
	}

	@Test
	@DisplayName("accept, no and gg are the typed equivalents of the strip buttons")
	void answers()
	{
		assertEquals(DuelCommand.Kind.ACCEPT, parse("accept").getKind());
		assertEquals(DuelCommand.Kind.ACCEPT, parse("yes").getKind());
		assertEquals(DuelCommand.Kind.DECLINE, parse("no").getKind());
		assertEquals(DuelCommand.Kind.DECLINE, parse("decline").getKind());
		assertEquals(DuelCommand.Kind.CONCEDE, parse("gg").getKind());
		assertEquals(DuelCommand.Kind.CONCEDE, parse("forfeit").getKind());
	}

	@Test
	@DisplayName("the generated command is short, and parses back to the same rules")
	void formatRoundTrips()
	{
		assertEquals("::duel testpurr trappy 1", DuelCommand.format("testpurr", DuelRules.parse("h-bs1"), Difficulty.HARD));
		assertEquals("::duel test_purr trappy 5 avg easy", DuelCommand.format("test purr", DuelRules.parse("e-av5"), Difficulty.HARD));
		String line = DuelCommand.format("Test Purr", DuelRules.parse("n-av3"), Difficulty.HARD);
		DuelCommand back = DuelCommand.parse(line.substring("::duel ".length()).split(" "), Difficulty.HARD);
		assertEquals("n-av3", back.getRules().canonical());
		assertEquals("Test Purr", back.getPlayer());
	}

	@Test
	@DisplayName("junk is a usage error with a readable usage line")
	void usage()
	{
		DuelCommand c = parse("");
		assertEquals(DuelCommand.Kind.USAGE, c.getKind());
		assertTrue(DuelCommand.USAGE.startsWith("Usage: ::duel <player> trappy"));
		assertEquals(DuelCommand.Kind.USAGE, parse("zezima trappy 7").getKind());
		assertEquals(DuelCommand.Kind.USAGE, parse("zezima trappy 3 sometimes").getKind());
	}
}

package com.trappychinchompa.duel;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

class DuelControllerTest
{
	private static final String ME = "Andrew";
	private static final String THEM = "Zezima";
	private static final DuelRules HARD_BS3 = DuelRules.parse("h-bs3");

	private final FakeRelaySocket socket = new FakeRelaySocket();
	private final List<String> notices = new ArrayList<>();
	private final List<DuelRecord> ready = new ArrayList<>();
	private final java.util.Set<String> blockList = new java.util.HashSet<>();
	private boolean blocked;
	private int changes;

	private final DuelController c = new DuelController("wss://relay.test/ws", socket, Runnable::run, (d, task) -> { },
		() -> blocked, notices::add, () -> changes++, ready::add, () -> blockList, new com.google.gson.Gson());

	private static Map<String, Object> map(Object... kv)
	{
		return FakeRelaySocket.map(kv);
	}

	private void online()
	{
		c.connect(ME, "12345", false, false);
		socket.up();
		socket.relay(map("t", "welcome", "name", ME, "v", 1));
		assertTrue(c.isOnline());
	}

	private String last(List<String> l)
	{
		return l.isEmpty() ? null : l.get(l.size() - 1);
	}

	@Test
	@DisplayName("a challenge goes out; their accept ends the lobby phase and the pushed record lands in the ledger")
	void challengeAcceptRecord()
	{
		online();
		assertTrue(c.challenge(THEM, HARD_BS3));
		assertEquals(DuelController.Phase.SENT, c.getPhase());
		assertEquals("challenge", socket.last().get("t"));
		assertEquals("h-bs3", ((Map<?, ?>) socket.last().get("data")).get("rules"));
		socket.relay(map("t", "accept", "from", THEM, "game", DuelController.GAME, "data", map("rules", "h-bs3")));
		assertEquals(DuelController.Phase.IDLE, c.getPhase());
		socket.relay(map("t", "duel", "record", DuelRecordTest.relayRecord("ACTIVE", "h-bs3", 3, List.of(), List.of(), List.of(), List.of(), null, null)));
		assertEquals(1, c.getLedger().duels().size());
		assertEquals(DuelRecord.Todo.PLAY, c.getLedger().duels().get(0).todo());
	}

	@Test
	@DisplayName("an incoming challenge is accepted through the relay; nothing starts locally")
	void incomingAccept()
	{
		online();
		socket.relay(map("t", "challenge", "from", THEM, "game", DuelController.GAME, "data", map("rules", "n-av5")));
		assertEquals(DuelController.Phase.INCOMING, c.getPhase());
		assertEquals(THEM, c.pendingChallenger());
		assertTrue(c.accept());
		assertEquals("accept", socket.last().get("t"));
		assertEquals("n-av5", ((Map<?, ?>) socket.last().get("data")).get("rules"));
		assertEquals(DuelController.Phase.IDLE, c.getPhase());
		assertNull(c.getPlayingId());
	}

	@Test
	@DisplayName("play with a revealed seed hands over the record; the finished game is reported; a minute in, a touch keeps it alive")
	void playAndReport()
	{
		online();
		socket.relay(map("t", "duel", "record", DuelRecordTest.relayRecord("ACTIVE", "h-bs3", 3, List.of(5), List.of(), List.of(), List.of(), null, null)));
		DuelRecord r = c.play("abc123");
		assertNotNull(r, "seed 2 is in the test record");
		assertEquals(2, r.nextGame());
		assertEquals("abc123", c.getPlayingId());
		c.tick(1_000);
		assertEquals("touch", socket.last().get("t"));
		c.tick(30_000);
		assertEquals("touch", socket.last().get("t"));
		c.gameEnded("abc123", 2, 4, List.of(0, 7, 14, 21), 60);
		assertEquals("report", socket.last().get("t"));
		assertEquals(2.0, socket.last().get("game"));
		assertEquals(4.0, socket.last().get("score"));
		assertNull(c.getPlayingId());
		assertNull(c.play("nope"));
		c.play("abc123");
		assertNull(c.play("abc123"), "a second Play while playing is refused");
	}

	@Test
	@DisplayName("play without a seed asks the relay to start the game; the record that comes back with it is handed to the canvas")
	void playAsksForTheSeed()
	{
		online();
		Map<String, Object> rec = DuelRecordTest.relayRecord("ACTIVE", "h-bs3", 3, List.of(5, 9), List.of(), List.of(), List.of(), null, null);
