	@Test
	@DisplayName("refusals: no relay, a dev toggle, a pending challenge, or challenging yourself")
	void refusals()
	{
		assertFalse(c.challenge(THEM, HARD_BS3));
		assertTrue(last(notices).toLowerCase().contains("relay"));
