package com.trappychinchompa.duel;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

class DuelRecordTest
{
	private static final Gson GSON = new Gson();
	private static final java.lang.reflect.Type MAP = new TypeToken<Map<String, Object>>()
	{
	}.getType();

	/** A record as the relay sends it, with the given reports and verdicts. */
	static Map<String, Object> relayRecord(String status, String rules, int stretchEnd,
		List<Integer> mine, List<Integer> theirs, List<Boolean> myVerdicts, List<Boolean> theirVerdicts, String winner, String reason)
	{
		StringBuilder reps = new StringBuilder();
		reps.append("\"Andrew\":[");
		for (int i = 0; i < mine.size(); i++)
		{
			reps.append(i == 0 ? "" : ",").append("{\"game\":").append(i + 1).append(",\"score\":").append(mine.get(i))
				.append(",\"flaps\":[0,7,14],\"ticks\":60}");
		}
		reps.append("],\"Zezima\":[");
		for (int i = 0; i < theirs.size(); i++)
		{
			reps.append(i == 0 ? "" : ",").append("{\"game\":").append(i + 1).append(",\"score\":").append(theirs.get(i))
				.append(",\"flaps\":[0,7,14],\"ticks\":70}");
		}
		reps.append("]");
		String result = winner == null && reason == null ? "null" : "{\"winner\":" + (winner == null ? "null" : "\"" + winner + "\"") + ",\"reason\":\"" + reason + "\"}";
		String json = "{\"id\":\"abc123\",\"game\":\"tc1\",\"kind\":\"duel\",\"rules\":\"" + rules + "\",\"players\":[\"Andrew\",\"Zezima\"],"
			+ "\"seeds\":{\"1\":\"1\",\"2\":\"2\"},\"created\":1000,\"deadline\":301000,"
			+ "\"reports\":{" + reps + "},\"verdicts\":{\"Andrew\":" + GSON.toJson(myVerdicts) + ",\"Zezima\":" + GSON.toJson(theirVerdicts) + "},"
			+ "\"stretchEnd\":" + stretchEnd + ",\"status\":\"" + status + "\",\"result\":" + result + ",\"games\":[]}";
		return GSON.fromJson(json, MAP);
	}

	@Test
	@DisplayName("a fresh record: my next game is 1, nothing to verify, time left from the deadline")
	void fresh()
	{
		DuelRecord r = DuelRecord.from(relayRecord("ACTIVE", "h-bs3", 3, List.of(), List.of(), List.of(), List.of(), null, null), "andrew");
		assertEquals("Zezima", r.getOpponent());
		assertEquals("h-bs3", r.getRules().canonical());
		assertEquals(1, r.nextGame());
		assertEquals(Long.valueOf(1L), r.seed(1));
		assertTrue(r.hasSeed(1));
		assertFalse(r.hasSeed(3));
		assertNull(r.seed(3));
		assertEquals(300_000L, r.timeLeft(1000));
		assertEquals(0L, r.timeLeft(400_000));
		assertEquals(DuelRecord.Todo.PLAY, r.todo());
		assertFalse(r.isDone());
	}

	@Test
	@DisplayName("once my stretch is in I wait; their reports are readable")
	void waitsOnceMyStretchIsIn()
	{
		DuelRecord r = DuelRecord.from(relayRecord("ACTIVE", "h-bs3", 3, List.of(5, 9, 2), List.of(8, 8), List.of(true), List.of(true, true, true), null, null), "Andrew");
		assertEquals(0, r.nextGame());
		assertEquals(DuelRecord.Todo.WAIT, r.todo());
		DuelRecord.Report theirs = r.theirReport(2);
		assertEquals(8, theirs.getScore());
		assertEquals(List.of(0, 7, 14), theirs.getFlaps());
		assertEquals(70, theirs.getTicks());
		assertEquals(9, r.myReport(2).getScore());
	}

	@Test
	@DisplayName("a sudden-death stretch asks for game 4 and labels it")
	void suddenDeath()
	{
		DuelRecord r = DuelRecord.from(relayRecord("ACTIVE", "n-bs3", 4, List.of(4, 4, 4), List.of(4, 4, 4), List.of(true, true, true), List.of(true, true, true), null, null), "Andrew");
		assertEquals(4, r.nextGame());
		assertFalse(r.hasSeed(4), "sudden death seed comes with start");
		assertTrue(r.isSuddenDeath(4));
		assertEquals("sudden death", r.gameLabel(4));
		assertEquals("game 2 of 3", r.gameLabel(2));
	}

	@Test
	@DisplayName("a settled record becomes an outcome with a You/Them table from my side")
	void outcome()
	{
		DuelRecord r = DuelRecord.from(relayRecord("DONE", "h-bs3", 3, List.of(5, 9, 2), List.of(8, 8, 8), List.of(true, true, true), List.of(true, true, true), "Andrew", "WIN"), "Andrew");
		assertTrue(r.isDone());
		assertEquals(DuelRecord.Todo.DONE, r.todo());
		DuelOutcome o = r.outcome();
		assertEquals("Andrew", o.getWinner());
		assertEquals(DuelOutcome.Reason.WIN, o.getReason());
		assertEquals(3, o.getGames().size());
		assertEquals(9, o.getGames().get(1).getMine());
		assertEquals(8, o.getGames().get(1).getTheirs());
		assertEquals("best 9 to 8", o.getScoreLine());
		DuelRecord theirs = DuelRecord.from(relayRecord("DONE", "h-bs3", 3, List.of(5, 9, 2), List.of(8, 8, 8), List.of(true, true, true), List.of(true, true, true), "Andrew", "WIN"), "Zezima");
		assertEquals("best 8 to 9", theirs.outcome().getScoreLine());
		assertEquals("Andrew", theirs.getOpponent());
		DuelRecord timeout = DuelRecord.from(relayRecord("DONE", "h-bs1", 1, List.of(5), List.of(), List.of(), List.of(true), "Andrew", "TIMEOUT"), "Zezima");
		assertEquals(DuelOutcome.Reason.DISCONNECT, timeout.outcome().getReason());
		DuelRecord nc = DuelRecord.from(relayRecord("DONE", "h-bs1", 1, List.of(), List.of(), List.of(), List.of(), null, "NO_CONTEST"), "Andrew");
		assertNull(nc.outcome().getWinner());
		assertEquals(DuelOutcome.Reason.NO_CONTEST, nc.outcome().getReason());
	}
}

package com.trappychinchompa.duel;

import java.util.List;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class DuelResultTextTest
{
	private static final String ME = "Andrew";
	private static final String THEM = "Zezima";
	private static final DuelRules HARD_BS3 = DuelRules.parse("h-bs3");

	private static DuelOutcome outcome(String winner, DuelOutcome.Reason reason)
	{
		return new DuelOutcome(winner, reason, List.of(
			new DuelOutcome.GameLine(1, 5, 8, false),
			new DuelOutcome.GameLine(2, 9, 8, false),
			new DuelOutcome.GameLine(3, 2, 8, false)), "best 9 to 8");
	}

	private static void ascii(String s)
	{
		for (char c : s.toCharArray())
		{
			assertTrue(c < 128, "non-ascii in: " + s);
		}
	}

	@Test
	@DisplayName("a plain win and loss name the opponent, the score line and the rules")
	void winAndLoss()
	{
		String win = DuelResultText.chatLine(outcome(ME, DuelOutcome.Reason.WIN), ME, THEM, HARD_BS3);
		assertEquals("Duel vs Zezima: you won, best 9 to 8 (Hard, best round of 3).", win);
		String loss = DuelResultText.chatLine(outcome(THEM, DuelOutcome.Reason.WIN), ME, THEM, HARD_BS3);
		assertEquals("Duel vs Zezima: you lost, best 9 to 8 (Hard, best round of 3).", loss);
		ascii(win);
		ascii(loss);
	}

	@Test
	@DisplayName("forfeits, failed checks and disconnects say who did what")
	void forfeitsAndCheats()
	{
		assertEquals("Duel vs Zezima: Zezima forfeited, you win.",
			DuelResultText.chatLine(outcome(ME, DuelOutcome.Reason.FORFEIT), ME, THEM, HARD_BS3));
		assertEquals("Duel vs Zezima: you forfeited, Zezima wins.",
			DuelResultText.chatLine(outcome(THEM, DuelOutcome.Reason.FORFEIT), ME, THEM, HARD_BS3));
		assertEquals("Duel vs Zezima: their score did not check out, you win.",
			DuelResultText.chatLine(outcome(ME, DuelOutcome.Reason.CHEAT), ME, THEM, HARD_BS3));
		assertEquals("Duel vs Zezima: your score did not check out, Zezima wins.",
			DuelResultText.chatLine(outcome(THEM, DuelOutcome.Reason.CHEAT), ME, THEM, HARD_BS3));
		assertEquals("Duel vs Zezima: Zezima ran out of time, you win.",
			DuelResultText.chatLine(outcome(ME, DuelOutcome.Reason.DISCONNECT), ME, THEM, HARD_BS3));
	}

	@Test
	@DisplayName("no contest and disputed results record no winner")
	void noWinner()
	{
		assertEquals("Duel vs Zezima: no contest.",
			DuelResultText.chatLine(outcome(null, DuelOutcome.Reason.NO_CONTEST), ME, THEM, HARD_BS3));
		assertEquals("Duel vs Zezima: disputed result, no winner.",
			DuelResultText.chatLine(outcome(null, DuelOutcome.Reason.DISPUTED), ME, THEM, HARD_BS3));
	}

	@Test
	@DisplayName("the card headline is short and shouts")
	void headlines()
	{
		assertEquals("YOU WIN!", DuelResultText.headline(outcome(ME, DuelOutcome.Reason.WIN), ME));
		assertEquals("YOU LOSE", DuelResultText.headline(outcome(THEM, DuelOutcome.Reason.WIN), ME));
		assertEquals("NO CONTEST", DuelResultText.headline(outcome(null, DuelOutcome.Reason.NO_CONTEST), ME));
		assertEquals("DISPUTED", DuelResultText.headline(outcome(null, DuelOutcome.Reason.DISPUTED), ME));
	}

	@Test
	@DisplayName("the reason line under the headline explains anything that was not a plain win")
	void reasonLines()
	{
		assertEquals("", DuelResultText.reasonLine(outcome(ME, DuelOutcome.Reason.WIN), ME, THEM));
		assertEquals("Zezima forfeited", DuelResultText.reasonLine(outcome(ME, DuelOutcome.Reason.FORFEIT), ME, THEM));
		assertEquals("You forfeited", DuelResultText.reasonLine(outcome(THEM, DuelOutcome.Reason.FORFEIT), ME, THEM));
		assertEquals("Their score did not check out", DuelResultText.reasonLine(outcome(ME, DuelOutcome.Reason.CHEAT), ME, THEM));
		assertEquals("Zezima ran out of time", DuelResultText.reasonLine(outcome(ME, DuelOutcome.Reason.DISCONNECT), ME, THEM));
		assertEquals("Nobody showed up", DuelResultText.reasonLine(outcome(null, DuelOutcome.Reason.NO_CONTEST), ME, THEM));
	}
}

package com.trappychinchompa.duel;

import com.trappychinchompa.Difficulty;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;

public class DuelRulesTest
{
	@Test
	public void everyRuleSetRoundTripsThroughItsCanonicalCode()
	{
		for (Difficulty d : Difficulty.values())
		{
			for (DuelRules.Metric m : DuelRules.Metric.values())
			{
				for (int series : new int[]{1, 3, 5})
				{
					DuelRules rules = new DuelRules(d, m, series);
					DuelRules back = DuelRules.parse(rules.canonical());
					assertEquals(rules, back);
				}
			}
		}
	}

	@Test
	public void canonicalCodesAreHumanGuessable()
	{
		assertEquals("h-bs3", new DuelRules(Difficulty.HARD, DuelRules.Metric.BEST_ROUND, 3).canonical());
		assertEquals("n-av5", new DuelRules(Difficulty.NORMAL, DuelRules.Metric.AVERAGE, 5).canonical());
		assertEquals("e-bs1", new DuelRules(Difficulty.EASY, DuelRules.Metric.BEST_ROUND, 1).canonical());
	}

	@Test
	public void describesItselfForPlayers()
	{
		assertEquals("Hard, best round of 3", DuelRules.parse("h-bs3").describe());
		assertEquals("Normal, average of 5", DuelRules.parse("n-av5").describe());
		assertEquals("Easy, best round of 1", DuelRules.parse("e-bs1").describe());
	}

	@Test
	public void rejectsAnythingOutsideTheGrammar()
	{
