package com.trappychinchompa.duel;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/** The socket seam: remembers opens, sends and closes; the test plays the relay. */
class FakeRelaySocket implements RelayClient.Socket
{
	static final Gson GSON = new Gson();
	static final java.lang.reflect.Type MAP = new TypeToken<Map<String, Object>>()
	{
	}.getType();

	final List<String> opened = new ArrayList<>();
	final List<Map<String, Object>> sent = new ArrayList<>();
	RelayClient.SocketListener listener;
	int closes;

	@Override
	public void open(String url, RelayClient.SocketListener listener)
	{
		opened.add(url);
		this.listener = listener;
	}

	@Override
	public void send(String text)
	{
		sent.add(GSON.fromJson(text, MAP));
	}

	@Override
	public void close()
	{
		closes++;
	}

	void up()
	{
		listener.onOpen();
	}

	void relay(Map<String, Object> msg)
	{
		listener.onText(GSON.toJson(msg));
	}

	void down()
	{
		listener.onClosed();
	}

	Map<String, Object> last()
	{
		return sent.get(sent.size() - 1);
	}

	List<Map<String, Object>> ofType(String t)
	{
		List<Map<String, Object>> out = new ArrayList<>();
		for (Map<String, Object> m : sent)
		{
			if (t.equals(m.get("t")))
			{
				out.add(m);
			}
		}
		return out;
	}

	static Map<String, Object> map(Object... kv)
	{
		Map<String, Object> m = new HashMap<>();
		for (int i = 0; i < kv.length; i += 2)
		{
			m.put((String) kv[i], kv[i + 1]);
		}
		return m;
	}
}

package com.trappychinchompa.duel;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.trappychinchompa.game.BoxTrap;
import com.trappychinchompa.game.FlappyGame;
import java.io.FileWriter;
import java.io.IOException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Writes replay vectors for the relay's JavaScript port of the simulation:
 * seeds, rules, autopilot flap traces, and the scores and gap centres the
 * Java game produces. `./gradlew golden` regenerates build/golden.json.
 */
public final class GoldenVectors
{
	private GoldenVectors()
	{
	}

	public static void main(String[] args) throws IOException
	{
		List<Map<String, Object>> vectors = new ArrayList<>();
		long[] seeds = {1L, 4242L, -77L, 9007199254740993L, Long.MIN_VALUE + 5, 123456789012345L};
		String[] rules = {"e-bs1", "n-bs3", "h-bs5", "n-av1"};
		int k = 0;
		for (long seed : seeds)
		{
			for (String code : rules)
			{
				DuelRules r = DuelRules.parse(code);
				// Three pilots per seed: cautious, greedy, and one that never launches.
				for (int pilot = 0; pilot < 3; pilot++)
				{
					vectors.add(vector(seed, r, pilot, k++));
				}
			}
		}
		Gson gson = new GsonBuilder().create();
		try (FileWriter w = new FileWriter(args.length > 0 ? args[0] : "build/golden.json"))
		{
			w.write(gson.toJson(vectors));
		}
		System.out.println("golden vectors: " + vectors.size());
	}

	private static Map<String, Object> vector(long seed, DuelRules rules, int pilot, int index)
	{
		DuelRun run = new DuelRun(seed, rules);
		List<Integer> flaps = new ArrayList<>();
		List<Integer> gaps = new ArrayList<>();
		int spawned = 0;
		int t = 0;
		int offset = pilot == 0 ? 15 : 4;
		int limit = pilot == 2 ? 300 : 20_000;
		if (pilot != 2)
		{
			run.flap();
			flaps.add(0);
		}
		while (t < limit && !run.ended())
		{
			FlappyGame game = run.game();
			int target = DuelRun.HEIGHT / 2;
			for (BoxTrap trap : game.getTraps())
			{
				if (trap.getX() + FlappyGame.TRAP_WIDTH > FlappyGame.CHIN_X - FlappyGame.CHIN_HALF_W)
				{
					target = trap.getGapCenter();
					break;
				}
			}
			if (pilot != 2 && game.getChinY() > target + offset && game.getChinVy() >= 0 && (index + t) % 3 != 0)
			{
				run.flap();
				flaps.add(t);
			}
			run.tick();
			t++;
			int total = game.getTraps().size() + game.getScore();
			if (total > spawned)
			{
				gaps.add(game.getTraps().get(game.getTraps().size() - 1).getGapCenter());
				spawned = total;
			}
		}
		Map<String, Object> v = new HashMap<>();
		v.put("seed", Long.toString(seed));
		v.put("rules", rules.canonical());
		v.put("flaps", flaps);
		v.put("ticks", run.totalTicks());
		v.put("score", run.score());
		v.put("ended", run.ended());
		v.put("gaps", gaps.subList(0, Math.min(gaps.size(), 12)));
		v.put("replay", new TrappyAdapter().replay(seed, rules, flaps, run.totalTicks()));
		return v;
	}
}

package com.trappychinchompa.duel;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotEquals;

/** The account id never leaves the client raw (Andrew, 2026-09-12:
 * "definitely add hashing"): the relay binds names to a SHA-256 of the
 * RuneLite account hash under the shared akaddons prefix, and keys that
 * again itself. Every AKAddons plugin must derive the same value, so one
 * name stays one account across plugins. */
class HashesTest
{
	@Test
	@DisplayName("the account id sent to the relay is a stable SHA-256 of the RuneLite account hash under the akaddons prefix, never the number itself")
	void accountId()
	{
		String id = Hashes.account(1234567890123L);
		assertEquals(Hashes.sha256Hex("akaddons:1234567890123"), id);
		assertEquals(64, id.length());
		assertFalse(id.contains("1234567890123"));
		assertEquals(id, Hashes.account(1234567890123L), "stable across calls and sessions");
		assertNotEquals(id, Hashes.account(1234567890124L));
	}
}

package com.trappychinchompa.duel;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class RelayClientTest
{
	private static class Recorder implements RelayClient.Lobby
	{
		final List<String> events = new ArrayList<>();
		Map<String, Object> lastRecord;
		List<Map<String, Object>> lastList;

		@Override
		public void connected(boolean online)
		{
			events.add("online:" + online);
		}

		@Override
		public void challenge(String from, String game, Map<String, Object> data)
		{
			events.add("challenge:" + from + ":" + game + ":" + data.get("rules"));
		}

		@Override
		public void answer(boolean accepted, String from, String game, Map<String, Object> data)
		{
			events.add((accepted ? "accept:" : "decline:") + from);
		}

		@Override
		public void offline(String to)
		{
			events.add("offline:" + to);
		}

		@Override
		public void sent(String to)
		{
			events.add("sent:" + to);
		}

		@Override
		public void share(String from, String game, String kind, Map<String, Object> data)
		{
			events.add("share:" + kind);
		}

		@Override
		public void who(List<String> online)
		{
			events.add("who:" + online);
		}

		@Override
		public void duel(Map<String, Object> record)
		{
			events.add("duel:" + record.get("id"));
			lastRecord = record;
		}

		@Override
		public void sync(List<Map<String, Object>> duels, Map<String, Object> history)
		{
			events.add("sync:" + duels.size() + ":" + (history == null ? "-" : history.get("wins")));
			lastList = duels;
		}

		@Override
		public void queued(String rules)
		{
			events.add("queued:" + rules);
		}

		@Override
		public void dequeued()
		{
			events.add("dequeued");
		}

		@Override
		public void board(String key, List<Map<String, Object>> top, boolean dev)
		{
			events.add("board:" + key + ":" + top.size() + (dev ? ":dev" : ""));
			lastList = top;
		}

		@Override
		public void ranks(String key, List<Map<String, Object>> top)
		{
			events.add("ranks:" + key + ":" + top.size());
		}

		@Override
		public void history(Map<String, Object> history)
		{
			events.add("history:" + history.get("wins"));
		}
	}

	private static Map<String, Object> map(Object... kv)
	{
		return FakeRelaySocket.map(kv);
	}

	private final FakeRelaySocket socket = new FakeRelaySocket();
	private final Recorder lobby = new Recorder();
	private final List<Long> delays = new ArrayList<>();
	private final RelayClient client = new RelayClient("wss://relay.test/ws", socket, Runnable::run,
		(delayMs, task) -> delays.add(delayMs), lobby, new com.google.gson.Gson());

	private String last(List<String> l)
	{
		return l.isEmpty() ? null : l.get(l.size() - 1);
	}

	@Test
	@DisplayName("connecting says hello with the name and game once the socket is up")
	void helloOnOpen()
	{
		client.connect("Andrew", "tc1", "12345", false, true);
		assertEquals(List.of("wss://relay.test/ws"), socket.opened);
		socket.up();
		assertEquals("hello", socket.last().get("t"));
		assertEquals("Andrew", socket.last().get("name"));
		assertEquals("tc1", socket.last().get("game"));
		assertEquals("12345", socket.last().get("account"));
		assertEquals(false, socket.last().get("hidden"));
		assertEquals(true, socket.last().get("dev"));
		socket.relay(map("t", "welcome", "name", "Andrew", "v", 1));
		assertTrue(client.isOnline());
		assertEquals("online:true", last(lobby.events));
	}

	@Test
	@DisplayName("lobby traffic goes out as JSON and comes back as callbacks")
	void lobbyRoundTrip()
	{
		client.connect("Andrew", "tc1", "12345", false, true);
		socket.up();
		client.challenge("Zezima", "tc1", map("rules", "h-bs3"));
		assertEquals("challenge", socket.last().get("t"));
		assertEquals("h-bs3", ((Map<?, ?>) socket.last().get("data")).get("rules"));
		socket.relay(map("t", "challenge", "from", "Zezima", "game", "tc1", "data", map("rules", "n-av5")));
		assertEquals("challenge:Zezima:tc1:n-av5", last(lobby.events));
		socket.relay(map("t", "accept", "from", "Zezima", "game", "tc1", "data", map()));
		assertEquals("accept:Zezima", last(lobby.events));
		socket.relay(map("t", "offline", "to", "Zezima"));
		assertEquals("offline:Zezima", last(lobby.events));
	}

	@Test
	@DisplayName("the duel book: reports, verdicts, concede, touch, compete and lookups round-trip")
	void duelBook()
	{
		client.connect("Andrew", "tc1", "12345", false, true);
		socket.up();
		client.report("abc", 2, 7, List.of(0, 7, 14), 60);
		assertEquals("report", socket.last().get("t"));
		assertEquals(2.0, socket.last().get("game"));
		assertEquals(List.of(0.0, 7.0, 14.0), socket.last().get("flaps"));
		client.start("abc", 2);
		assertEquals("start", socket.last().get("t"));
		assertEquals(2.0, socket.last().get("game"));
		client.concede("abc");
		assertEquals("concede", socket.last().get("t"));
		client.touch("abc");
		assertEquals("touch", socket.last().get("t"));
		client.compete("tc1", "h-bs1");
		assertEquals("h-bs1", socket.last().get("rules"));
		client.uncompete();
		assertEquals("uncompete", socket.last().get("t"));
		client.board("tc1", "h");
		client.ranks("tc1", "h");
		client.history("tc1");
		assertEquals("history", socket.last().get("t"));

		socket.relay(map("t", "duel", "record", map("id", "abc", "status", "ACTIVE")));
		assertEquals("duel:abc", last(lobby.events));
		socket.relay(map("t", "sync", "duels", List.of(map("id", "abc")), "history", map("wins", 3)));
		assertEquals("sync:1:3.0", last(lobby.events));
		socket.relay(map("t", "queued", "rules", "h-bs1"));
		assertEquals("queued:h-bs1", last(lobby.events));
		socket.relay(map("t", "dequeued"));
		assertEquals("dequeued", last(lobby.events));
		socket.relay(map("t", "board", "key", "h", "top", List.of(map("name", "Zezima", "score", 12))));
		assertEquals("board:h:1", last(lobby.events));
		socket.relay(map("t", "board", "key", "h", "dev", true, "top", List.of()));
		assertEquals("board:h:0:dev", last(lobby.events));
		socket.relay(map("t", "ranks", "key", "h", "top", List.of()));
		assertEquals("ranks:h:0", last(lobby.events));
		socket.relay(map("t", "history", "wins", 2));
		assertEquals("history:2.0", last(lobby.events));
	}

	@Test
	@DisplayName("a dropped socket reconnects with backoff and re-hellos; disconnect stops it")
	void reconnects()
	{
		client.connect("Andrew", "tc1", "12345", false, true);
		socket.up();
		socket.down();
		assertEquals("online:false", last(lobby.events));
		assertEquals(List.of(1000L), delays);
		client.retry();
		socket.down();
		assertEquals(List.of(1000L, 2000L), delays);
		client.retry();
		socket.up();
		assertEquals("hello", socket.last().get("t"));
		socket.relay(map("t", "welcome", "name", "Andrew", "v", 1));
		socket.down();
		assertEquals(1000L, delays.get(delays.size() - 1));
		client.disconnect();
		assertFalse(client.isOnline());
		int before = delays.size();
		socket.down();
		assertEquals(before, delays.size());
	}

	@Test
	@DisplayName("junk from the relay is ignored")
	void junkIgnored()
	{
		client.connect("Andrew", "tc1", "12345", false, true);
		socket.up();
		socket.listener.onText("not json");
		socket.listener.onText("{\"t\":5}");
		socket.relay(map("t", "mystery"));
		assertTrue(lobby.events.isEmpty());
	}
}

package com.trappychinchompa.duel;

import com.trappychinchompa.Difficulty;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class SeriesTest
{
	private static Series series(String code)
	{
		return new Series(DuelRules.parse(code));
	}

	@Test
	@DisplayName("best round of 3: the single highest score wins, even with a worse total")
	void bestRoundTakesTheHighestSingleScore()
	{
		Series s = series("h-bs3");
		s.record(1, 5, 8);
		s.record(2, 9, 8);
		s.record(3, 2, 8);
		assertTrue(s.complete());
		assertTrue(s.compare() > 0);
	}

	@Test
	@DisplayName("average of 3: the higher total wins, compared as integer sums")
	void averageTakesTheHigherSum()
	{
		Series s = series("h-av3");
		s.record(1, 5, 8);
		s.record(2, 9, 8);
		s.record(3, 2, 8);
		assertTrue(s.complete());
		assertTrue(s.compare() < 0);
	}

	@Test
	@DisplayName("a tied single game goes to sudden death and the first difference decides")
	void tiedBestOfOneGoesToSuddenDeath()
	{
		Series s = series("n-bs1");
		s.record(1, 4, 4);
		assertFalse(s.complete());
		assertEquals(2, s.nextGameIndex());
		assertTrue(s.lineFor(2).isSuddenDeath());
		s.record(2, 3, 3);
		assertFalse(s.complete());
		s.record(3, 2, 1);
		assertTrue(s.complete(), "a sudden-death game decides on its own score");
		assertTrue(s.compare() > 0);
		assertEquals(3, s.lines().size());
		assertEquals("best 4 to 4, sudden death 2 to 1", s.scoreLine());
	}

	@Test
	@DisplayName("average of 5 with equal sums keeps playing until they differ")
	void tiedAverageSumsKeepPlaying()
	{
		Series s = series("e-av5");
		int[][] scores = {{1, 5}, {5, 1}, {3, 3}, {2, 4}, {4, 2}};
		for (int i = 0; i < 5; i++)
		{
			s.record(i + 1, scores[i][0], scores[i][1]);
		}
		assertFalse(s.complete());
		assertEquals(6, s.nextGameIndex());
		s.record(6, 1, 0);
		assertTrue(s.complete());
		assertTrue(s.compare() > 0);
	}

	@Test
	@DisplayName("all games are played: a 2-0 lead in best round of 3 is not yet complete")
	void everyGameIsPlayed()
	{
		Series s = series("h-bs3");
		s.record(1, 9, 1);
		s.record(2, 9, 1);
		assertFalse(s.complete());
		assertEquals(3, s.nextGameIndex());
		assertFalse(s.lineFor(3).isSuddenDeath());
	}

	@Test
	@DisplayName("the score line reads games won for best round and totals for average")
	void scoreLine()
	{
		Series bs = series("h-bs3");
		bs.record(1, 5, 8);
		bs.record(2, 9, 8);
		bs.record(3, 2, 8);
		assertEquals("best 9 to 8", bs.scoreLine());
		Series av = series("h-av3");
		av.record(1, 5, 8);
		av.record(2, 9, 8);
		av.record(3, 2, 8);
		assertEquals("total 16 to 24", av.scoreLine());
		assertEquals(Difficulty.HARD, av.getRules().getDifficulty());
	}
}

package com.trappychinchompa.duel;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** The Java replay, kept for the golden vectors the relay's simulation port is checked against. */
public final class TrappyAdapter
{
	public int replay(long seed, DuelRules rules, List<Integer> flapTicks, int totalTicks)
	{
		List<Integer> flaps = new ArrayList<>(flapTicks);
		Collections.sort(flaps);
		DuelRun run = new DuelRun(seed, rules);
		int total = Math.min(totalTicks, DuelRun.MAX_TICKS);
		int next = 0;
		for (int t = 0; t < total && !run.ended(); t++)
		{
			while (next < flaps.size() && flaps.get(next) <= t)
			{
				if (flaps.get(next) == t)
				{
					run.flap();
				}
				next++;
			}
			run.tick();
		}
		return run.score();
	}
}

package com.trappychinchompa.duel;

import com.trappychinchompa.game.BoxTrap;
import com.trappychinchompa.game.FlappyGame;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class TrappyAdapterTest
{
	private static final DuelRules HARD = DuelRules.parse("h-bs3");
	private static final DuelRules NORMAL = DuelRules.parse("n-bs3");
	private static final long SEED = 4242L;

	/** Flap whenever the chin sinks below the next gap's centre. Deterministic, mediocre. */
	private static void autopilot(DuelRun run, int maxTicks)
	{
		run.flap();
		for (int t = 0; t < maxTicks && !run.ended(); t++)
		{
			FlappyGame game = run.game();
			int target = DuelRun.HEIGHT / 2;
			for (BoxTrap trap : game.getTraps())
			{
				if (trap.getX() + FlappyGame.TRAP_WIDTH > FlappyGame.CHIN_X - FlappyGame.CHIN_HALF_W)
				{
					target = trap.getGapCenter();
					break;
				}
			}
			if (game.getChinY() > target + 15 && game.getChinVy() >= 0)
			{
				run.flap();
			}
			run.tick();
		}
	}

	@Test
	@DisplayName("two runs on the same seed and rules spawn the same first twenty gaps")
	void sameSeedSameTraps()
	{
		List<Integer> a = spawnOrder(new DuelRun(SEED, HARD), 20);
		List<Integer> b = spawnOrder(new DuelRun(SEED, HARD), 20);
		assertEquals(20, a.size());
		assertEquals(a, b);
		assertNotEquals(a, spawnOrder(new DuelRun(SEED + 1, HARD), 20));
	}

	/** Gap centres in spawn order: the newest tower is always last in the list. */
	private static List<Integer> spawnOrder(DuelRun run, int wanted)
	{
		List<Integer> centres = new ArrayList<>();
		run.game().setTrapInvincible(true);
		run.flap();
		int spawned = 0;
		while (centres.size() < wanted && !run.ended())
		{
			if (run.game().getChinY() > DuelRun.HEIGHT / 2.0)
			{
				run.flap();
			}
			run.tick();
			List<BoxTrap> traps = run.game().getTraps();
			// Spawn count = towers on screen + towers already passed (scored).
			int total = traps.size() + spawnedBefore(run);
			if (total > spawned)
			{
				centres.add(traps.get(traps.size() - 1).getGapCenter());
				spawned = total;
			}
		}
		return centres;
	}

	private static int spawnedBefore(DuelRun run)
	{
		return run.game().getScore();
	}

	@Test
	@DisplayName("a recorded run replays headlessly to exactly its own score")
	void replayReproducesTheRecordedScore()
	{
		DuelRun run = new DuelRun(SEED, NORMAL);
		autopilot(run, 20_000);
		assertTrue(run.ended());
		assertTrue(run.score() > 0, "autopilot should clear at least one trap, scored " + run.score());
		int replayed = new TrappyAdapter().replay(SEED, NORMAL, run.flapTicks(), run.totalTicks());
		assertEquals(run.score(), replayed);
	}

	@Test
	@DisplayName("a trace with one flap removed replays to a different score")
	void tamperedTraceReplaysDifferently()
	{
		DuelRun run = new DuelRun(SEED, NORMAL);
		autopilot(run, 20_000);
		List<Integer> flaps = new ArrayList<>(run.flapTicks());
		flaps.remove(flaps.size() / 2);
		int replayed = new TrappyAdapter().replay(SEED, NORMAL, flaps, run.totalTicks());
		assertNotEquals(run.score(), replayed);
	}

	@Test
	@DisplayName("a run that never launches ends at the ten-minute cap with no score, and replay honours the cap")
	void cappedAtTenMinutes()
	{
		DuelRun run = new DuelRun(SEED, HARD);
		for (int i = 0; i < DuelRun.MAX_TICKS + 500; i++)
		{
			run.tick();
		}
		assertTrue(run.ended());
		assertEquals(DuelRun.MAX_TICKS, run.totalTicks());
		assertEquals(0, run.score());
		assertEquals(0, new TrappyAdapter().replay(SEED, HARD, List.of(), DuelRun.MAX_TICKS + 500));
	}

	@Test
	@DisplayName("flaps after the run has ended are not recorded")
	void flapsAfterTheEndAreIgnored()
	{
		DuelRun run = new DuelRun(SEED, HARD);
		run.flap();
		while (!run.ended())
		{
			run.tick();
		}
		int recorded = run.flapTicks().size();
		run.flap();
		assertEquals(recorded, run.flapTicks().size());
		assertFalse(run.flapTicks().isEmpty());
	}

}

package com.trappychinchompa.game;

import java.util.Collections;
import java.util.Set;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

class BackgroundThemeTest
{
	private static final Set<String> NONE = Collections.emptySet();

	@Test
	@DisplayName("the level ladder is strictly ascending, opens at level 1, and caps at 99")
	void ladderShape()
	{
		int previous = 0;
		int levelZones = 0;
		for (BackgroundTheme theme : BackgroundTheme.values())
		{
			if (theme.isAchievementGated())
			{
				continue;
			}
			assertTrue(theme.getUnlockLevel() > previous,
				theme + " unlocks after the zone before it");
			assertTrue(theme.getUnlockLevel() <= HunterXp.MAX_LEVEL, theme + " is reachable");
			previous = theme.getUnlockLevel();
			levelZones++;
		}
		assertEquals(11, levelZones, "eleven level-ladder zones");
		assertEquals(99, BackgroundTheme.PRIFDDINAS.getUnlockLevel(), "the crystal city caps the ladder");
	}

	@Test
	@DisplayName("highestUnlocked walks the ladder with level and earned trophies")
	void highestUnlocked()
	{
		assertEquals(BackgroundTheme.FELDIP_MARSH, BackgroundTheme.highestUnlocked(1, NONE));
		assertEquals(BackgroundTheme.LUMBRIDGE, BackgroundTheme.highestUnlocked(10, NONE));
		assertEquals(BackgroundTheme.ARDOUGNE, BackgroundTheme.highestUnlocked(50, NONE));
		assertEquals(BackgroundTheme.PRIFDDINAS, BackgroundTheme.highestUnlocked(99, NONE));
		assertEquals(BackgroundTheme.PANDEMONIUM, BackgroundTheme.highestUnlocked(1,
			Collections.singleton("score_EASY_250")), "trophies count as newest");
	}

	@Test
	@DisplayName("achievement-gated zones answer only to their achievements, ANY of them")
	void gatedZones()
	{
		assertFalse(BackgroundTheme.PANDEMONIUM.isUnlocked(99, NONE), "no level opens it");
		assertTrue(BackgroundTheme.PANDEMONIUM.isUnlocked(1,
			Collections.singleton("score_EASY_250")));
		assertTrue(BackgroundTheme.INFERNO.isUnlocked(1,
			Collections.singleton("streak_NORMAL_50x20")), "the Normal streak opens it");
		assertTrue(BackgroundTheme.INFERNO.isUnlocked(1,
			Collections.singleton("streak_HARD_50x20")), "so does the Hard streak");
		assertFalse(BackgroundTheme.INFERNO.isUnlocked(99, NONE));
	}

	@Test
	@DisplayName("a level jump reports the newest zone it unlocked, or nothing")
	void newlyUnlocked()
	{
		assertNull(BackgroundTheme.newlyUnlocked(3, 9), "no unlock crossed");
		assertEquals(BackgroundTheme.LUMBRIDGE, BackgroundTheme.newlyUnlocked(9, 10));
		assertEquals(BackgroundTheme.AL_KHARID, BackgroundTheme.newlyUnlocked(10, 39),
			"the newest of several crossed unlocks wins");
		assertEquals(BackgroundTheme.PRIFDDINAS, BackgroundTheme.newlyUnlocked(90, 99),
			"gated zones never appear here");
		assertNull(BackgroundTheme.newlyUnlocked(99, 99), "nothing left to unlock");
	}
}

package com.trappychinchompa.game;

import java.util.Collections;
