	{
		int previous = -1;
		int ranked = 0;
		for (ChinSkin skin : ChinSkin.values())
		{
			if (skin.getUnlockAchievementId() != null)
			{
				continue;
			}
			assertTrue(skin.getUnlockHighScore() > previous,
